
/** 进入游戏错误码 */
export enum ENTER_GAME_ERR_CODE {
    /** 成功 */
    SUCCESS,
    /** IP限制 */
    IP_RESTRICT,
    /** 篡改URL */
    INVALID_URL
}

/** LOGO播放类型 */
export enum LOGO_PLAY_TYPE {
    /** 默认加载 */
    DEFAULT = 1,
    /** 自定义加载 */
    CUSTOM,
    /** 不加载 */
    NONE
}


export class GameConst {

    /** app游戏版本文件 */
    public static APP_GAMES_CONFIG: string = 'games_config.json';

    /** 没有竖板loading图的游戏id */
    public static NON_VER_LOADING_ID = [
        1000006, 1000008, 1000100, 1000101, 3000197,
        3000206, 4000033, 320000101
    ];

    /** 是否有竖板loading图 */
    public static isHasVerLoading(gameId: number): boolean {
        if (this.NON_VER_LOADING_ID.indexOf(gameId) == -1)
            return true;
        return false;
    }

    /** 显示横竖版按钮的游戏id */
    public static SHOW_VER_BTN_GAME_ID = [
        3500199, 3500189, 3000195, 320000101
    ];
    public static isShowScreenBtn(gameId: number): boolean {
        if (this.SHOW_VER_BTN_GAME_ID.indexOf(gameId) >= 0)
            return true;
        return false;
    }
}
