import { _decorator, Component, Node, EventHandler, ProgressBar, Slider, Mask, UITransform } from 'cc';
const { ccclass, property } = _decorator;

@ccclass('PMaskSlider')
export class PMaskSlider extends Component {
    @property({ displayName: "progressMask", type: UITransform })
    progressMask: UITransform = null!;
    @property({ displayName: "progressBar", type: UITransform })
    progressBar: UITransform = null!;
    @property({ displayName: "slider", type: Slider })
    slider: Slider = null!;

    sliderEventHandler:{target:unknown, callback:Function} = null!;
    // sliderEventCallback:Function = null!;

    start () {
        let sliderEventHandler = new EventHandler();
        sliderEventHandler.component = "PMaskSlider";
        sliderEventHandler.handler = "sliderEvent";
        sliderEventHandler.target = this.node;
        this.slider.slideEvents.push(sliderEventHandler);
    }
    registerSliderEventCallback(cb:Function,target:any){
        let sliderEventHandler:{target:unknown, callback:Function} = <{target:unknown, callback:Function}>{};
        sliderEventHandler.target = target;
        sliderEventHandler.callback = cb;
        this.sliderEventHandler = sliderEventHandler;
    }
    sliderEvent(){
        // this.progressBar.getComponent(Sprite)!.fillRange = this.slider.progress;
        // this.progressMask.contentSize.set(this.progressBar.width*this.slider.progress);
        this.progressMask.width=this.progressBar.width*this.slider.progress;
        if(this.sliderEventHandler){
            let target = this.sliderEventHandler.target;
            this.sliderEventHandler.callback.bind(target)(this.slider.progress);
        }
    }
    private setProgress(progress:number){
        this.slider.getComponent(Slider)!.progress = progress;
        // this.progressBar.getComponent(Sprite)!.fillRange = progress;
        // this.progressMask.contentSize.set(this.progressBar.width*progress);
        this.progressMask.width=this.progressBar.width*progress;

    }
    public get progress(): number {
        return this.slider.getComponent(Slider)!.progress;
    }
    public set progress(progress:number) {
        this.setProgress(progress);
    }

}
