
import {
    _decorator,
    Node,
    Asset,
    Camera
} from "cc";
import {
    StatisticsEvent,
} from "../common/define/EnumDefine";

import { CtrlBase } from "./CtrlBase";
import { Global } from "./Global";
import { LoginStatistics } from "../common/define/StatisticsDefine";
import { eventTrig, StatisticsManager } from "../mgr/StatisticsManager";
import UIUtils from "../framework/ui/UIUtils";
import { EntryManager } from "../framework/hall/entry/EntryManager";
import { ResUtil } from "../framework/utils/ResUtil";
import LogUtil from "../common/utils/LogUtil";
import { CustomEventMgr } from "../mgr/CustomEventMgr";
import { EventType } from "../common/define/EventDefine";
import AudioManager from "../framework/manager/AudioManager";
const { ccclass, property } = _decorator;

@ccclass("GameCtrl")
export class GameCtrl extends CtrlBase {
    @property({ displayName: "mainUiLayer", type: Node })
    public mainUiLayer: Node = null!;

    @property({ displayName: "bg", type: Node })
    public bg: Node = null!;

    @property({ displayName: "camera", type: Camera })
    public camera: Camera = null!;

    @property({ displayName: "wssCacert", type: Asset })
    public wssCacert: Asset = null!;

    /** web音乐开关控制 */
    private _webMusicSwitch: number = 1;

    protected onLoad() {
        Global.gameCtrl = this;
        Global.wssCacert = this.wssCacert;
        EntryManager.getInstance().init();
        eventTrig(StatisticsEvent.LOADED_RES_SUCCESS);
        StatisticsManager.getInstance().loginReport(
            LoginStatistics.loadSuccess
        );
        StatisticsManager.getInstance().loginReport(
            LoginStatistics.loadTimes,
            true
        );
        window.addEventListener('message', this.message.bind(this));
    }

    start() {
    }

    /**
     * 网页游戏返回主界面的时候
     */
    public gameBack(isShowQuickPop: boolean = true) {
        UIUtils.hideLoading();
        EntryManager.getInstance().isInGame = false;
    }

    public gameBackAndSaveMusicSwitch(musicSwitch: boolean) {
    }

    private doConnectLogin(cb?: Function) {
    }

    autoPopAdvertisements: Array<any> = [];


    private message(event) {
        let str = event.data;
        let json = JSON.parse(str);
        if (!json)
            return;
        let funcName = json['functionName'];
        switch (funcName) {
            case 'closeRecordView': {
                CustomEventMgr.fire(EventType.WEB_CLOSE_RECORD_VIEW, event);
                break;
            }
            case 'closeHelpView': {
                CustomEventMgr.fire(EventType.WEB_CLOSE_HELP_VIEW, event);
                break;
            }
            case 'loaded': {
                CustomEventMgr.fire(EventType.WEB_LOADED, event);
                break;
            }
            case 'webOpenPlayback': {
                this.webMusicSwitch = 0;
                AudioManager.Instance().setMusicEnabled();
                CustomEventMgr.fire(EventType.WEB_OPEN_PLAY_BACK, event);
                break;
            }
            case 'webClosePlayback': {
                this.webMusicSwitch = 1;
                AudioManager.Instance().setMusicEnabled();
                CustomEventMgr.fire(EventType.WEB_CLOSE_PLAY_BACK, event);
                break;
            }
        }
    }

    /** web控制游戏音乐-开关 0关闭 1开启  */
    set webMusicSwitch(open: number) {
        this._webMusicSwitch = open;
    }
    get webMusicSwitch(): number {
        return this._webMusicSwitch;
    }

    public loginSuccess(data: any) {
        if (!data.succ) {
            return;
        }

        //获取配置表
        ResUtil.loadCocosVersionConfig(() => {
            LogUtil.debug("c2sgamelist");
        });
    }

    public doReconnect() {
        Global.svrTimeMS = -1;
        this.doConnectLogin(() => {
            UIUtils.hideLoading();
        });
    }

    protected onDestroy(): void {
        window.removeEventListener('message', this.message);
    }
}