import { _decorator, Component, math, Node, ShadowsInfo, tiledLayerAssembler, tweenUtil, Vec2, Vec3 } from 'cc';
import { Eventer } from '../../framework/Eventer';
import { GameEventType } from '../../../bundles/gamesCommon/script/GameEventType';
const { ccclass, property } = _decorator;

/** 从一个节点移到另一个节点 */
@ccclass('MoveToNode')
export class MoveToNode extends Component {

    private _fromNode: Node
    private _toNode: Node
    private _time: number
    private _callback: Function

    private _curTime: number
    private _isMove: boolean = false
    private _startX: number
    private _startY: number
    private get x(): number {
        return this.node.worldPosition.x
    }
    private get y(): number {
        return this.node.worldPosition.y
    }
    private get t_x(): number {
        return this._toNode.worldPosition.x
    }
    private get t_y(): number {
        return this._toNode.worldPosition.y
    }
    private get f_x(): number {
        if (this._fromNode)
            return this._fromNode.worldPosition.x

        return this._startX
    }
    private get f_y(): number {
        if (this._fromNode)
            return this._fromNode.worldPosition.y

        return this._startY
    }

    start() {

    }

    protected onDestroy(): void {

    }


    update(deltaTime: number) {
        if (!this._isMove) return
        if (!this._toNode || !this._toNode.isValid) return
        //if (!this._fromNode || !this._fromNode.isValid) return
        if (!this.node || !this.node.isValid) return

        if (this._time <= 0) {
            this.endMove()
            return
        }

        this._curTime += deltaTime
        let radio = Math.min(1, this._curTime / this._time)
        let x = math.lerp(this.f_x, this.t_x, radio)
        let y = math.lerp(this.f_y, this.t_y, radio)
        this.node.setWorldPosition(x, y, 0)

        if (radio >= 1) {
            this.endMove()
        }
    }

    startTo(fromNode: Node, toNode: Node, moveTime: number, callback: Function) {
        if (this._isMove) return
        this._fromNode = fromNode
        this._toNode = toNode
        this._time = moveTime
        this._callback = callback
        this._curTime = 0
        this._isMove = true
        this._startX = this.x
        this._startY = this.y
    }

    endMove() {
        this.node.setWorldPosition(this.t_x, this.t_y, 0)
        this._isMove = false
        this._callback?.()
    }

    stopMove() {
        this._isMove = false;
        this._callback = null;
    }

}

