/**
 *  bundle管理器
 */
import { Eventer } from "../Eventer";
import { HotUpdate } from "../update/IHotUpdate";
import { HotUpdateManager } from "../update/HotUpdateManager";
import { Singleton } from "../Singleton";
import { EntryDelegate } from "../hall/entry/EntryDelegate";
import { EntryManager } from "../hall/entry/EntryManager";
import { BUNDLE_RESOURCES, UNKNOWN } from "../hall/HallDefind";
import { assetManager, AssetManager, sys } from "cc";
import { ELOADER_STATE } from "../../common/define/EnumDefine";
import { Global } from "../../main/Global";

export class BundleManager extends Singleton<BundleManager>() {
    private curBundle: HotUpdate.BundleConfig = null!;
    public isLoading = false;
    /**正在下载的id */
    downloadingId: number = 0;
    protected isEngineBundle(key: any) {
        if (
            key == AssetManager.BuiltinBundleName.INTERNAL ||
            key == AssetManager.BuiltinBundleName.MAIN ||
            key == AssetManager.BuiltinBundleName.RESOURCES ||
            key == AssetManager.BuiltinBundleName.START_SCENE
        ) {
            return true;
        }
        return false;
    }
    /** 删除已经加载的bundle */
    public removeLoadedBundle(delegate: EntryDelegate, excludeBundles?: string[]) {
        if (!excludeBundles) {
            excludeBundles = delegate.getPersistBundle();
        }
        let loaded: string[] = [];
        assetManager.bundles.forEach((bundle, key) => {
            //引擎内置包不能删除
            if (!this.isEngineBundle(key)) {
                loaded.push(key);
            }
        });
        let i = loaded.length;
        while (i--) {
            let bundle = loaded[i];
            if (excludeBundles.indexOf(bundle) == -1) {
                //在排除bundle中找不到，直接删除
                EntryManager.getInstance().exitBundle(bundle, false);
            }
        }
    }

    /**
     *  获取Bundle
     * @param bundle Bundle名|Bundle
     **/
    public getBundle(bundle: BUNDLE_TYPE) {
        if (bundle) {
            if (typeof bundle == "string") {
                return assetManager.getBundle(bundle);
            }
            return bundle;
        }
        return null;
    }

    public getBundleName(bundle: BUNDLE_TYPE): string {
        if (bundle) {
            if (typeof bundle == "string") {
                return bundle;
            } else {
                return bundle.name;
            }
        }
        Log.e(`输入参数错误 : ${bundle}`);
        return UNKNOWN;
    }

    /**
     * 外部接口 进入Bundle
     * @param config 配置
     */
    public enterBundle(config: HotUpdate.BundleConfig, delegate: EntryDelegate) {
        // if (this.isLoading) {
        //     if (delegate) delegate.onBundleLoading(config);
        //     Log.d("正在更新游戏，请稍等");
        //     return;
        // }
        this.curBundle = config;
        this.isLoading = true;
        HotUpdateManager.getInstance().bundlesConfig[this.curBundle.bundle] = config;

        let versionInfo = HotUpdateManager.getInstance().bundlesConfig[this.curBundle.bundle];
        this.checkUpdate(versionInfo, delegate);
    }

    /** 检测子游戏更新 */
    private checkUpdate(versionInfo: HotUpdate.BundleConfig, delegate: EntryDelegate) {
        Log.d(`检测更新信息:${versionInfo.name}(${versionInfo.bundle})`);
        let eventName = HotUpdate.Event.HOTUPDATE_DOWNLOAD + `_${versionInfo.name}`
        let bundle: string | undefined = this.curBundle.bundle;
        if (this.curBundle.bundle == BUNDLE_RESOURCES) {
            bundle = undefined;
        }
        if (versionInfo.hasUpdate === false) {
            this.isLoading = false;
            if (delegate) delegate.onAreadyUpToData(versionInfo, HotUpdate.Code.ALREADY_UP_TO_DATE, HotUpdate.State.UP_TO_DATE);
            return;
        }
        HotUpdateManager.getInstance().checkUpdate((code, state) => {
            Log.d(`game checkUpdate code=${code}, state=${state}`);
            if (code == HotUpdate.Code.ALREADY_UP_TO_DATE) {
                //已经是最新版本
                this.isLoading = false;
                if (delegate) delegate.onAreadyUpToData(versionInfo, code, state);
            } else if (code == HotUpdate.Code.NEW_VERSION_FOUND) {
                if (state == HotUpdate.State.UP_TO_DATE) {
                    //已经是最新版本
                    this.isLoading = false;
                    if (delegate) delegate.onAreadyUpToData(versionInfo, code, state);
                } else {
                    Eventer.getInstance().offName(eventName, this);
                    //有新版本
                    Eventer.getInstance().on(
                        eventName,
                        this.onDownload.bind(this, delegate, versionInfo.name),
                        this
                    );
                    this.downloadingId = versionInfo.gameId;
                    Log.d(`检测到${versionInfo.name}(${versionInfo.bundle})有新的版本`);
                    if (delegate) delegate.onNewVersionFund(versionInfo, code);
                }

            } else if (state == HotUpdate.State.TRY_DOWNLOAD_FAILED_ASSETS) {
                //尝试重新下载之前下载失败的文件
                Eventer.getInstance().on(
                    eventName,
                    this.onDownload.bind(this, delegate, versionInfo.name),
                    this
                );
                this.downloadingId = versionInfo.gameId;
                Log.d(`正在尝试重新下载之前下载失败的资源`);
                if (delegate) delegate.onDownloadFailed(versionInfo, code, state);
            } else if (
                code == HotUpdate.Code.ERROR_DOWNLOAD_MANIFEST ||
                code == HotUpdate.Code.ERROR_NO_LOCAL_MANIFEST ||
                code == HotUpdate.Code.ERROR_PARSE_MANIFEST
            ) {
                //下载manifest文件失败
                this.isLoading = false;
                if (delegate) delegate.onDownloadManifestFailed(versionInfo, code, state);
            } else if (code == HotUpdate.Code.CHECKING) {
                //当前正在检测更新
                Log.d(`正在检测更新!!`);
                if (delegate) delegate.onCheckingVersion(versionInfo, code, state);
            } else {
                this.isLoading = false;
                Log.d(`检测更新当前状态 code : ${code} state : ${state}`);
                if (delegate) delegate.onOtherReason(versionInfo, code, state);
            }
        }, bundle);
    }

    public loadBundle(delegate: EntryDelegate, bundleName?: string) {
        bundleName = bundleName ?? this.curBundle.bundle;
        let config = delegate.getEntryConfig(bundleName) ?? this.curBundle;
        let bundle = this.getBundle(bundleName);
        if (bundle) {
            Log.d(`${config.bundle}已经加载在缓存中，直接使用`);
            Log.d(`${this.downloadingId}，${config.gameId}`);
            this.isLoading = false;
            Log.d(`load bundle0 :==========$${EntryManager.getInstance().enterGameId}=, ${this.downloadingId}, ${config.gameId}==`)
            if (this.downloadingId == config.gameId) {
                Eventer.getInstance().emit(HotUpdate.Event.DOWNLOAD_PROGRESS, {
                    id: config.gameId,
                    state: ELOADER_STATE.UNZIP_SUCC
                });
            } else if (delegate) delegate.onLoadBundleComplete(config, bundle);
            return;
        }
        this.isLoading = true;
        Log.d(`loadBundle : ${bundleName}`);
        let bundleFunc = (err, bundle) => {
            this.isLoading = false;
            if (err) {
                Log.e(`load bundle : ${bundleName} fail !!! ${err}`);
                if (this.downloadingId == config.gameId) {
                    Eventer.getInstance().emit(HotUpdate.Event.DOWNLOAD_PROGRESS, {
                        id: config.gameId,
                        state: ELOADER_STATE.UNZIP_FAIL
                    });
                    if (config.bundle == this.downloadingId.toString()) this.downloadingId = 0;
                } else if (delegate) delegate.onLoadBundleError(config, err);
            } else {
                Log.d(`load bundle1 : ${bundleName}, gameId:${config.gameId} success !!!`);
                Log.d(`load bundle2 :==========$${EntryManager.getInstance().enterGameId}=, ${this.downloadingId}, ${config.gameId}==`)
                if (this.downloadingId == config.gameId) {
                    Eventer.getInstance().emit(HotUpdate.Event.DOWNLOAD_PROGRESS, {
                        id: config.gameId,
                        state: ELOADER_STATE.UNZIP_SUCC
                    });
                    if (config.bundle == this.downloadingId.toString()) this.downloadingId = 0;
                } else if (delegate) {
                    delegate.onLoadBundleComplete(config, bundle);
                }
            }
        };
        if (sys.isBrowser) {
            if (!Global.debug) {
                let name = `${Global.cdn}/gamec/game/${bundleName}`;
                let version = EntryManager.getInstance().getBundleVersion(bundleName);
                if (version) assetManager.loadBundle(name, { version: version }, bundleFunc);
            } else
                assetManager.loadBundle(bundleName, bundleFunc);
        } else {
            assetManager.loadBundle(bundleName, bundleFunc);
        }
    }

    private onDownload(delegate: EntryDelegate, bundle: string, info: HotUpdate.DownLoadInfo) {
        Log.d(`onDownload1=${bundle}==${JSON.stringify(info)}`);
        if (info.code == HotUpdate.Code.UPDATE_FINISHED) {
            this.isLoading = false;
            let eventName = HotUpdate.Event.HOTUPDATE_DOWNLOAD + `_${bundle}`
            Eventer.getInstance().offName(eventName, this);
            Log.d(`${bundle} 更新成功!`);
        } else if (
            info.code == HotUpdate.Code.UPDATE_FAILED ||
            info.code == HotUpdate.Code.ERROR_NO_LOCAL_MANIFEST ||
            info.code == HotUpdate.Code.ERROR_DOWNLOAD_MANIFEST ||
            info.code == HotUpdate.Code.ERROR_PARSE_MANIFEST ||
            info.code == HotUpdate.Code.ERROR_DECOMPRESS
        ) {
            this.isLoading = false;
            Log.e(`${bundle} 更新失败!`);
            let eventName = HotUpdate.Event.HOTUPDATE_DOWNLOAD + `_${bundle}`
            Eventer.getInstance().offName(eventName, this);
        }
        if (delegate) {
            // let config = delegate.getEntryConfig(bundle) ?? this.curBundle;
            Log.d(`onDownload2==${bundle}=,${this.curBundle.bundle}==${delegate.getEntryConfig(bundle).gameId}=`)
            // if (this.curBundle.bundle == bundle) {
            delegate.onDownloading(delegate.getEntryConfig(bundle), info);
            // }
        }
    }
}
