import { sys } from "cc";

export enum LogLevel {
    DEBUG,
    INFO,
    WARN,
    ERROR,
}

export default class LogUtil {
    // static logLevel: LogLevel = LogLevel.ERROR;
    public static logLevel: LogLevel = LogLevel.DEBUG;

    public static init(debug: boolean) {
        if (debug) {
            this.logLevel = LogLevel.DEBUG;
        } else {
            this.logLevel = LogLevel.WARN;
        }
    }

    public static log(msg: any, ...args: any[]) {
        if (this.logLevel > LogLevel.DEBUG) {
            return;
        }
        console.log("GAMELOG: " + msg, ...args);
    }

    public static debug(msg: any, ...args: any[]) {
        if (this.logLevel > LogLevel.DEBUG) {
            return;
        }
        console.log("GAMEDEBUG: " + msg, ...args);
    }

    public static info(msg: any, ...args: any[]) {
        if (this.logLevel > LogLevel.INFO) {
            return;
        }
        console.log("GAMEINFO: " + msg, ...args);
    }

    public static warn(msg: any, ...args: any[]) {
        if (this.logLevel > LogLevel.WARN) {
            return;
        }

        console.warn("GAMEWARN: " + msg, ...args);
    }

    public static error(msg: any, ...args: any[]) {
        if (this.logLevel > LogLevel.ERROR) {
            return;
        }
        console.error("GAMEERROR: " + msg, ...args);
    }
}
