
import {
    assetManager,
    Node,
    AudioClip,
    AudioSource,
    Component,
    _decorator,
} from "cc";


const { ccclass, property, menu } = _decorator;

@ccclass
@menu("runtime/AudioEffectManager")
export default class AudioEffectManager extends Component {

    public AudioClipNode: Node[] = [];
    onLoad() {

    }

    public play(url: string, clip: AudioClip, volume: number, loop = false) {
        if (!this.node || !this.node.isValid) {
            return
        }
        let clipNode = this.getFreeClipNode(url)
        clipNode.getComponent(AudioSource).loop = loop
        clipNode.getComponent(AudioSource).clip = clip
        clipNode.getComponent(AudioSource).volume = volume
        clipNode.getComponent(AudioSource).play()
        this.AudioClipNode.push(clipNode)
    }

    public stop(url: string) {
        let clipNode = this.getClipNode(url)
        if (clipNode) {
            clipNode.getComponent(AudioSource).stop()
            clipNode.getComponent(AudioSource).clip = null
        }
    }

    public stopAll(exceptLoop = true) {
        for (let index = 0; index < this.AudioClipNode.length; index++) {
            const clipNode = this.AudioClipNode[index];
            let adS = clipNode.getComponent(AudioSource);
            if (exceptLoop) {
                if (!adS.loop) {
                    adS.stop();
                    adS.clip = null;
                }
            } else {
                adS.stop();
                adS.clip = null;
            }
        }
    }

    public pauseAll() {
        for (let i = 0; i < this.AudioClipNode.length; ++i) {
            let adS = this.AudioClipNode[i]?.getComponent(AudioSource);
            if (adS) {
                if (!adS.loop) {
                    adS.stop();
                    adS.clip = null;
                } else {
                    adS.pause();
                }
            }
        }
    }

    public resumeAll() {
        for (let i = 0; i < this.AudioClipNode.length; ++i) {
            let adS = this.AudioClipNode[i]?.getComponent(AudioSource);
            if (adS) {
                if (adS.loop) {
                    adS.play();
                }
            }
        }
    }

    private getClipNode(url: string, remove = false): Node {
        for (let index = 0; index < this.AudioClipNode.length; index++) {
            const clipNode = this.AudioClipNode[index];
            if (clipNode.name == url && clipNode.getComponent(AudioSource).clip && clipNode.getComponent(AudioSource).playing) {
                if (remove)
                    this.AudioClipNode.splice(index, 1)
                return clipNode
            }
        }
        return null
    }

    private getFreeClipNode(url: string) {
        let clipNode = null
        for (let index = 0; index < this.AudioClipNode.length; index++) {
            const clipN = this.AudioClipNode[index];
            let adS = clipN.getComponent(AudioSource);
            if (adS.clip == null || (!adS.loop && !adS.playing)) {
                clipNode = clipN;
                this.AudioClipNode.splice(index, 1)
                break
            }
        }
        if (!clipNode) {
            clipNode = this.createClipNode(url)
        }
        clipNode.name = url
        return clipNode
    }

    private createClipNode(url: string): Node {
        let clipNode = new Node(url)
        clipNode.parent = this.node
        clipNode.addComponent(AudioSource)
        return clipNode
    }
}
