export class GameEvent {
    private static pre = "GAME_EVENT_";
    /**更新收藏状态*/
    public static UPDATE_COLLECTION = GameEvent.pre + "UPDATE_COLLECTION";
    /**更新下载状态*/
    public static UPDATE_DOWNLOAD = GameEvent.pre + "UPDATE_DOWNLOAD";
    /**更新游戏列表*/
    public static ON_UPDATE_GAMELIST = GameEvent.pre + "ON_UPDATE_GAMELIST";
    /**添加一个数据到下载列表*/
    public static ADD_LOADER_GAME_DATA = GameEvent.pre + "ADD_LOADER_GAME_DATA";
    /**取消下载*/
    public static CANCEL_DOWNLOAD = GameEvent.pre + "CANCEL_DOWNLOAD";
    /**重新下载*/
    public static REFRESH_DOWNLOAD = GameEvent.pre + "REFRESH_DOWNLOAD";
    /**更新显示*/
    public static ON_UPDATE_SHOW_GAME = GameEvent.pre + "ON_UPDATE_SHOW_GAME";
    /**当遂进入游戏*/
    public static ON_ENTER_GAME = GameEvent.pre + "ON_ENTER_GAME";

    /**开关*/
    public static ON_SWITCH_CHANGE = GameEvent.pre + "ON_SWITCH_CHANGE";
}
