import { SpriteAtlas, AssetManager, Prefab, Asset, resources, assetManager, SpriteFrame, Sprite, isValid, Texture2D } from 'cc';
import { Singleton } from '../Singleton';
export interface CCBundleLoadProgressCallback {
    (finish: number, total: number, item: AssetManager.RequestItem): void;
}

/**
 * 资源管理
 */
export default class ResourceManager extends Singleton<ResourceManager>() {
    /**图集缓存 */
    private atlas: Record<string, SpriteAtlas> = {};
    /**bundle缓存 */
    private bundles: Record<string, Promise<AssetManager.Bundle>> = {};
    /**prefab缓存 */
    private prefabs: Record<string, Prefab> = {};

    /**
     * 加载资源通用接口
     * @param path 路径
     * @param type 类型
     * @param compCallback 完成回调
     * @param bundleName bundle名称
     * @param progressCallback 进度回调
     * 
     * @example 
    ```js
        ResourceManager.getInstance().loadRes("textures/common/avatar_pet_1", SpriteFrame)
        .then((spriteFrame: SpriteFrame)=>{
            sprite.spriteFrame = spriteFrame;
        })
        ResourceManager.getInstance().loadRes("prefabs/NoticeTips", Prefab)
        .then((prefab: Prefab)=>{
            let node = instantiate(prefab);
            this.node.addChild(node);
        })
    ```
     */
    public async loadResAsync<T extends typeof Asset>(
        path: string,
        type: T,
        bundleName?: string,
        progressCallback?: CCBundleLoadProgressCallback
    ): Promise<Asset> {
        let name = path.substring(path.lastIndexOf('/') + 1);
        let assets = this.getAssetsCache(type);
        if (assets[name]) {
            return assets[name];
        }
        return new Promise((resolve, reject) => {
            let onProgress = function (
                completedCount: number,
                totalCount: number,
                item: AssetManager.RequestItem
            ) {
                if (progressCallback) {
                    progressCallback(completedCount, totalCount, item);
                }
            };
            let onComplete = function (error: Error, asset: Asset) {
                if (error) {
                    console.warn(`Load Asset ${path} Error ${error}`);
                    reject(`Load Asset ${path} Error ${error}`);
                    return;
                }
                assets[name] = asset;
                resolve(asset);
            };
            if (bundleName) {
                this.getBundleAsync(bundleName).then((bundle) => {
                    bundle.load(path, type, onProgress, onComplete);
                });
            } else {
                resources.load(path, type, onProgress, onComplete);
            }
        });
    }

    /**
     * 根据类型获取缓存列表
     * @param type
     * @returns
     */
    private getAssetsCache(type: typeof Asset) {
        let assets = {};
        if (type instanceof Prefab) {
            assets = this.prefabs;
        } else if (type instanceof SpriteAtlas) {
            assets = this.atlas;
        }
        return assets;
    }

    /**
     * 获取bundle
     * @param bundleName
     * @returns
     */
    public async getBundleAsync(bundleName: string = 'resources') {
        let bundle = assetManager.getBundle(bundleName);
        if (bundle) return Promise.resolve(bundle);
        //防止连续调用同名bundle报错
        if (this.bundles[bundleName]) return this.bundles[bundleName];
        this.bundles[bundleName] = new Promise<AssetManager.Bundle>((resolve, reject) => {
            assetManager.loadBundle(bundleName, null, (error, bundle) => {
                error ? reject() : resolve(bundle);
                delete this.bundles[bundleName];
            });
        });
        return this.bundles[bundleName];
    }

    /**
     * 获取图集中的精灵帧
     * @param atlasPath 图集名称
     * @param spriteFrameName 精灵名称
     */
    public async getAtlasSpriteFrameAsync(
        atlasPath: string,
        spriteFrameName: string
    ): Promise<SpriteFrame> {
        return new Promise((resolve, reject) => {
            this.loadResAsync(atlasPath, SpriteAtlas).then((atlas: SpriteAtlas) => {
                resolve(atlas.getSpriteFrame(spriteFrameName));
            });
        });
    }
}
