export class i18nConfig {

    /** i18n信息 */
    public static main: any;

    public static initConfig(config) {
        i18nConfig.main = i18nConfig.paser(config["i18n_main"]);
    }

    private static paser(cfg: any): any {
        let ans = {};
        for (let i in cfg) {
            let content = cfg[i];
            ans[i] = content;
        }
        return ans;
    }

}