import { Node, _decorator } from "cc";
import { UIView, UIZIndex } from "./UIView";
import { Eventer } from "../Eventer";
import { Events } from "../Events";
import { LogoComp } from "../../common/components/LogoComp";
import { GameModel } from "../../main/GameModel";
const { ccclass, property } = _decorator;


@ccclass("UILogoView")
export class UILogoView extends UIView {

    @property({ displayName: '游戏启动插屏', type: Node })
    logoNode: Node = null;

    init(...args): void {
        this.node.zIndex = UIZIndex.notice;
    }

    public onOpen(...args): void {
        super.onOpen(...args);
        this.changeScreen();
        this.addEvent();
        this.playLogo();
    }

    /**
     * 播放logo
     */
    private playLogo() {
        // this.logoNode.getComponent(LogoComp).play(this.logoPlayEnd.bind(this));
        this.logoPlayEnd();
    }

    /**
     * 播放logo结束
     */
    private logoPlayEnd() {
        GameModel.getInstance().logoPlayed = true;
        // Eventer.getInstance().emit(Events.LogoPlayEnd);
        this.close();
    }

    private changeScreen(): void {
    }

    private addEvent() {
        Eventer.getInstance().on(Events.ScreenSwitchEvent, this.changeScreen, this);
    }

    protected onDestroy(): void {
        Eventer.getInstance().offName(Events.ScreenSwitchEvent, this);
    }
}