import { Component, EditBox, _decorator, director, sys } from "cc";
import { Eventer } from "../../framework/Eventer";
import { Events } from "../../framework/Events";
import { Global } from "../../main/Global";
import { EOSID } from "../define/EnumDefine";
import UIAdapter from "../../framework/ui/UIAdapter";
import { CCUtils } from "../utils/CCUtils";
import { UIManager } from "../../framework/ui/UIManager";
import { ScreenType } from "../../framework/ui/UIView";
import { GameUtils } from "../utils/GameUtil";
import { GameConst } from "../../main/GameConst";
const { ccclass, property } = _decorator;

@ccclass('ScreenSwitchCmp')
export class ScreenSwitchCmp extends Component {

    @property({ type: Boolean, displayName: '自动横竖屏功能是否生效' })
    public autoScreen: Boolean = true;

    onLoad() {
        this.initLandscreen();
    }

    start() {

        if (sys.os == sys.OS.IOS)
            window.addEventListener('orientationchange', this.orientationChange.bind(this))
        else
            screen.orientation.addEventListener('change', this.change.bind(this))
        this.resizeAgain();
    }

    /** 横竖屏切换响应事件 */
    private change(event) {
        const type = event?.target?.type;
        const angle = event?.target?.angle;

        this.unschedule(this.resizeAgain.bind(this));
        this.scheduleOnce(this.resizeAgain.bind(this), 0.1);

        if (type == "portrait-primary" || type == "portrait-secondary") {
            Global.gameScreenType = ScreenType.Portrait;
        } else {
            Global.gameScreenType = ScreenType.Landscape;
        }

        Log.w("orientation_change", type, angle)
    }

    /** 横竖屏响应事件 */
    private orientationChange() {
        this.unschedule(this.resizeAgain.bind(this));
        this.scheduleOnce(this.resizeAgain.bind(this), 0.1);

        let allNodes = CCUtils.getAllChildrenRecursion(director.getScene().getChildByName("Canvas"));
        let uilayerNodes = CCUtils.getAllChildrenRecursion(UIManager.getInstance().uiLayer.node);
        allNodes = allNodes.concat(uilayerNodes.concat());
        for (let i = 0; i < allNodes.length; i++) {
            if (allNodes[i].getComponent(EditBox) && allNodes[i].getComponent(EditBox).isFocused() == true) {
                // allNodes[i].getComponent(EditBox).blur();
                this.scheduleOnce(() => {
                    window.dispatchEvent(new Event("orientationchange"));
                }, 1);
                return;
            }
        }
    }

    private initLandscreen() {
        let mode = GameUtils.getScreensMode();
        if (mode == ScreenType.Portrait) {
            Global.gameScreenType = ScreenType.Portrait;
        } else {
            Global.gameScreenType = ScreenType.Landscape;
        }
    }

    private resizeAgain() {
        if (!GameConst.isShowScreenBtn(Global.gameId)) {
            this.initLandscreen();
            Eventer.getInstance().emit(Events.ScreenSwitchEvent);
        }
        UIAdapter.initResolution();
        // window.dispatchEvent(new Event("resize"));
    }

    protected onDestroy(): void {
        window.removeEventListener('orientationchange', this.orientationChange.bind(this))
        screen.orientation.removeEventListener('change', this.change.bind(this))
    }
}