import { _decorator, Component, Node, Button, Label, instantiate, EventTouch, v3 } from 'cc';
import { UIButtonState } from '../../framework/ui/basic_ui/UIButtonState';
import AudioManager from '../../framework/manager/AudioManager';
import { WithDrawCtrl } from '../../mgr/WithDrawCtrl';
import { SoundDefine } from '../define/ResDefine';
const { ccclass, property } = _decorator;

@ccclass('DropDownList2')
export class DropDownList2 extends Component {
    @property({ displayName: "bgNode", type: Node, tooltip: "弹窗背景，不赋值则无背景" })
    bgNode: Node = null!;
    @property({ displayName: "btnOpenMenu", type: Node, tooltip: "打开menu按钮" })
    btnOpenMenu: Node = null!;
    @property({ displayName: "btnLabel", type: Label, tooltip: "打开menu按钮的标题" })
    btnLabel: Label = null!;
    @property({ displayName: "arrow", type: Node, tooltip: "open 按钮的箭头" })
    arrow: Node = null!;

    @property({ displayName: "listNode", type: Node, tooltip: "menu列表" })
    listNode: Node = null!;
    @property({ displayName: "itemTemp", type: UIButtonState, tooltip: "menu内的item" })
    itemTemp: UIButtonState = null!;

    private numberList: Array<string> = [];
    private itemArr: Array<Node> = [];

    curNum = "";
    curIndex = -1;
    start() {
        this.bindEvents();
    }

    initList(numberList: Array<string> = []) {
        this.removeList();
        this.numberList = numberList;
        for (let i = 0; i < numberList.length; i++) {
            let num = numberList[i];
            let item: Node = instantiate(this.itemTemp.node);
            item.parent = this.itemTemp.node.parent;
            item.active = true;
            let labelNode:Node=item.getComponent(UIButtonState)!.normalNode.getChildByName("Label");
            labelNode.getComponent(Label)!.string = num.toString();
            labelNode=item.getComponent(UIButtonState)!.pressedNode.getChildByName("selLabel");
            labelNode.getComponent(Label)!.string = num.toString();
            item.getChildByName("selectIcon").active=false;

            this.itemArr.push(item);
            // item.on(Node.EventType.TOUCH_END, this.itemClick, this);
            item.getComponent(UIButtonState).touchEndedFun=this.itemClick.bind(this);
        }
        if (this.itemArr && this.itemArr.length > 0) {
            if (!WithDrawCtrl.instance.selBankCardIdx || WithDrawCtrl.instance.selBankCardIdx < 0) {
                WithDrawCtrl.instance.selBankCardIdx = 0;
            }
            if (WithDrawCtrl.instance.selBankCardIdx >= this.itemArr.length) {
                WithDrawCtrl.instance.selBankCardIdx = this.itemArr.length - 1;
            }
            let num = this.numberList[WithDrawCtrl.instance.selBankCardIdx];
            this.curNum = num;
            this.curIndex = WithDrawCtrl.instance.selBankCardIdx;
            this.btnLabel.string = this.curNum;

            this.itemArr[this.curIndex].getComponent(UIButtonState).select = true;
            this.itemArr[this.curIndex].getChildByName("selectIcon").active=true;
            this.itemArr[this.curIndex].getComponent(UIButtonState).enabled = false;
        }
    }

    private itemClick(curTarget: UIButtonState) {
        // let curTarget = event.getCurrentTarget();
        this.selectItem(curTarget.node);
        this.setListNodeVisible(false);
    }

    private selectItem(item: Node) {
        let index = this.itemArr.indexOf(item);
        if (index == -1) {
            return;
        }
        this.itemArr[this.curIndex].getComponent(UIButtonState).select = false;
        this.itemArr[this.curIndex].getChildByName("selectIcon").active=false;
        this.itemArr[this.curIndex].getComponent(UIButtonState).enabled = true;

        WithDrawCtrl.instance.selBankCardIdx = index;
        let num = this.numberList[index];
        this.curNum = num;
        this.curIndex = index;
        this.btnLabel.string = this.curNum;
        this.itemArr[this.curIndex].getComponent(UIButtonState).select = true;
        this.itemArr[this.curIndex].getChildByName("selectIcon").active=true;
        this.itemArr[this.curIndex].getComponent(UIButtonState).enabled = false;
    }

    private removeList() {
        for (let i = 0; i < this.itemArr.length; i++) {
            this.itemArr[i].destroy();
        }
        this.itemArr = [];
        this.numberList = [];
    }

    private bindEvents() {
        this.btnOpenMenu.on(Node.EventType.TOUCH_END, () => {
            let isVisible = !this.listNode.active;
            this.setListNodeVisible(isVisible);
        }, this)
    }

    private onBg(evt: Event): void {
        this.setListNodeVisible(false);
    }

    setListNodeVisible(isVisible: boolean) {
        this.listNode.active = isVisible;
        if (this.bgNode) {
            this.bgNode.active = isVisible;
            if (isVisible == true) {
                this.bgNode.on(Node.EventType.TOUCH_END, this.onBg, this);
            }
            else {
                this.bgNode.off(Node.EventType.TOUCH_END, this.onBg, this);
            }
        }
        if (this.listNode.active == true) {
            this.arrow.setRotationFromEuler(v3(0, 0, 180));
        } else {
            this.arrow.setRotationFromEuler(v3(0, 0, 0));
        }
    }

}