/**
 * http封装 ，数据为json
 */

import LogUtil from "../../utils/LogUtil";
import { HttpRespPack } from "./HttpRespPack";

export default class NetHttp {
    private xhr: XMLHttpRequest = null!;
    private onProgressCb: Function = null!;
    private onSuccCb: (msg: HttpRespPack, userdata: any) => void = null!;
    private onFailCb: (msg: HttpRespPack, userdata: any) => void = null!;
    private respThisArg: any = null!; //返回的自定义内容

    public init(respThisArg: any) {
        this.respThisArg = respThisArg;
        let xhr = new XMLHttpRequest();
        this.xhr = xhr;
        xhr.onreadystatechange = () => {
            if (4 === xhr.readyState) {
                //数据返回
                if (xhr.status >= 200 && xhr.status < 400) {
                    if (xhr.response) {
                        let data = null;
                        try {
                            data = JSON.parse(xhr.response);
                        } catch (err) {
                            LogUtil.warn("http error data!", xhr.response);
                        }
                        this.onSucc(data);
                    }
                } else {
                    this.onFail();
                }
            }
        };
        xhr.onprogress = this.onProgress;
        xhr.onabort = () => {
            LogUtil.log("http resquest abort!");
        };
        xhr.ontimeout = () => {
            LogUtil.log("http request time out ++++++++++++");
            this.onFail();
        };
        xhr.onerror = () => {
            LogUtil.log("http request warn +++++++++");
            this.onFail();
        };
    }

    public sendPost(
        url: string,
        data: string,
        succ: (msg: HttpRespPack, userdata: any) => void,
        fail: (msg: HttpRespPack, userdata: any) => void,
        contentType: HTTP_CONTENT_TYPE = HTTP_CONTENT_TYPE.JSON
    ) {
        this.onSuccCb = succ;
        this.onFailCb = fail;
        this.xhr.open("POST", url);
        this.xhr.setRequestHeader(
            "Content-Type",
            `${contentType}`,
        );
        LogUtil.log(`send post: url=${url},   data=${data}`);
        try {
            this.xhr.send(data);
        } catch (e) {
            LogUtil.warn("send post warn");
        }
    }

    public sendGet(
        url: string,
        data: string,
        succ: (msg: HttpRespPack, userdata: any) => void,
        fail: (msg: HttpRespPack, userdata: any) => void,
        contentType: HTTP_CONTENT_TYPE = HTTP_CONTENT_TYPE.URLENCODED
    ) {
        this.onSuccCb = succ;
        this.onFailCb = fail;

        LogUtil.debug("sendGet, url:" + url);
        this.xhr.open("GET", url);
        this.xhr.setRequestHeader(
            "Content-Type",
            `${contentType}`
        );
        try {
            this.xhr.send(data);
        } catch (e) {
            LogUtil.warn("send get warn");
        }
    }

    private onProgress(event: ProgressEvent): void {
        if (event.lengthComputable) {
            var percent: any = event.loaded / event.total;
        }
        if (this.onProgressCb) {
            this.onProgressCb(percent);
        }
    }

    private onFail() {
        if (this.onFailCb) {
            let httpRespPack = new HttpRespPack();
            httpRespPack.init(false, null);

            this.onFailCb(httpRespPack, this.respThisArg);
        }
        this.clearCB();
    }

    private onSucc(data: any) {
        if (this.onSuccCb) {
            let httpRespPack = new HttpRespPack();
            httpRespPack.init(true, data);

            this.onSuccCb(httpRespPack, this.respThisArg);
        }
        this.clearCB();
    }

    private clearCB() {
        this.onProgressCb = null!;
        this.onSuccCb = null!;
        this.onFailCb = null!;
    }
}


export class HTTP_CONTENT_TYPE {
    static readonly JSON: string = 'application/json';
    static readonly URLENCODED: string = 'application/x-www-form-urlencoded';
    static readonly TEXTPLAIN: string = 'text/plain';
}