import { Component, _decorator } from "cc";

const {ccclass, property} = _decorator;

interface IEventData {
    func: Function;
    target: any;
    isActive: boolean;
}

interface IEvent {
    [eventName: string]: IEventData[];
}

@ccclass("CustomEventMgr")
export class CustomEventMgr {
    public static handle: IEvent = {};
    private static isDispatching = 0;
    private static buffLists:any = {};

    public static on(eventName: string, cb:Function, target?: any){
        if(!this.handle[eventName]){
            this.handle[eventName] = [];
        }

        const data: IEventData = { func: cb, target: target, isActive: true};
        this.handle[eventName].push(data);
    }

    public static off(eventName: string, cb: Function, target?: any){
        const list = this.handle[eventName];
        if(!list || list.length <=0){
            return;
        }

        for (let i = 0; i < list.length; i++) {
            const event = list[i];
            if(event.isActive && event.func === cb && (!target || target === event.target)){
                if (this.isDispatching > 0) {
                    event.isActive = false;
                    let buffList = this.buffLists[eventName];
                    if (!buffList) {
                        buffList = [];
                        this.buffLists[eventName] = buffList;
                    }
                    buffList.push(i);
                } else {
                    list.splice(i, 1);
                }
                
                break;
            }
        }
    }
    public static offAll(eventName: string){
        
        const list = this.handle[eventName];
        if(!list || list.length <=0){
            return;
        }
        for (let i = 0; i < list.length; i++) {
            const event = list[i];
            if(event.isActive){
                if (this.isDispatching > 0) {
                    event.isActive = false;
                    let buffList = this.buffLists[eventName];
                    if (!buffList) {
                        buffList = [];
                        this.buffLists[eventName] = buffList;
                    }
                    buffList.push(i);
                } else {
                    list.splice(i, 1);
                }
            }
        }

    }

    public static fire(eventName: string, ...args:any){
        const list = this.handle[eventName];
        if (!list || list.length <= 0) {
            return;
        }

        this.isDispatching++;
        for (let i = 0; i < list.length; i++) {
            const event = list[i];
            event.func.apply(event.target, args);
        }
        this.isDispatching--;
        if (this.isDispatching <= 0) {
            this.clearBuffList();
        }
    }

    private static clearBuffList() {
        for (let eventName in this.buffLists) {

            let list = this.handle[eventName];
            if(!list || list.length <=0){
                return;
            }

            let buffList: [] = this.buffLists[eventName]; 
            buffList = buffList.sort((a, b)=>{
                return a - b;
            });

            for (let i = buffList.length-1; i >= 0 ; --i) {
                list.splice(buffList[i], 1);
            }
            delete this.buffLists[eventName];
        }
    }
}
