import { EOS, EOSID, IUser } from "../define/EnumDefine";
import StorageUtil from "../utils/StorageUtil";

export default class PlatformApi {
    os: EOS = EOS.NULL;
    user: IUser = null!;
    /**
     * 初始化平台API
     */
    init(): void { }
    /**
     * 登陆，协议号：10
     * @param device_type  系统类型，1：iOS,2：Android
     * @param device_token  用于push message的 token
     * @param account 帐户名
     * @param password 密码
     // * @param openid 第三方登陆的openid
     // * @param token 第三方登陆的token
     */
    login(device_type: EOSID, device_token: string, account: string, password: string) {
        let openid;
        let token;
        let user = this.user;
        if (user) {
            openid = user.userId;
            token = user.token;
        }
        if (account) {
            StorageUtil.saveAccount(account, password);
        }
    }

    /**
     * 在当前应用打开网页
     * @param url
     */

    openWebView(url: string) { }
    /**
     * 用外部浏览器打开网页
     * @param url
     */
    openURL(url: string) { }

    handlerPlatformMessage(message: string) { }

    setClipboard(text: string): boolean {
        return false;
    }

    restartGame(): void { }

    /**
     * 是否ipad
     */
    get isiPad(): boolean {
        let isIPad = this.isSafari && !this.isiPhone && 'ontouchend' in document;
        return isIPad
    }

    /**
     * 是否iphone
     */
    get isiPhone(): boolean {
        var ua = navigator.userAgent;
        let isiPhone = ua.indexOf("iPhone") != -1 && ua.indexOf("Version") != -1;
        return isiPhone;
    }

    /**
     * 是否safari
     */
    get isSafari(): boolean {
        var ua = navigator.userAgent;
        let isSafari = ua.indexOf("Safari") != -1 && ua.indexOf("Version") != -1; //通过浏览器，机型和touch事件判断
        return isSafari;
    }

    /**
     * 是否Mac
     */
    get isMac() {
        return /macintosh|mac os x/i.test(navigator.userAgent);
    };
}
