import { ESUCC, ECODE } from "../../common/define/EnumDefine";
import { Protocol } from "../../common/define/ProtDefine";
import { User } from "../../model/User";
import { Singleton } from "../Singleton";
import UIUtils from "../ui/UIUtils";
import SocketManager from "./SocketManager";

const TIMEOUT = 1000;

export class NetAdaptor extends Singleton<NetAdaptor>() {
    static bAdaptor: boolean = true;
    private timeout1: any = null;
    private curCode: number = Protocol.Heart;
    private curFunc: Function = null;
    public isShowLoading = false;

    /**
     * 消息发送
     * @param code 消息号
     * @param data 消息体
     */
    sendMessage<T>(code: number, data?: T): void {
        SocketManager.getInstance().sendMessage(code, data);
    }

    /**
     * 消息接收
     * @param code
     * @param data
     */
    recvMessage<T>(code: number, data?: T) {
        this.onErrorHandler(code, data);
        this.clearTimeOut(code);
    }

    /**
     * 设置网络超时
     * @param code
     */
    setNetTimeOut(func: Function) {
        SocketManager.getInstance().sendMessage(Protocol.Heart);
        this.curFunc = func;
        this.timeout1 = setTimeout(() => {
            UIUtils.showLoading();
            this.isShowLoading = true;
        }, TIMEOUT);
    }

    clearTimeOut(code: number) {
        if (code == this.curCode) {
            if (this.timeout1) {
                clearTimeout(this.timeout1);
                this.timeout1 = null;
                if (this.curFunc) this.curFunc();
                this.curFunc = null;
            }
        } else {
            this.closeLoadingView();
        }
    }

    closeLoadingView() {
        if (this.isShowLoading) {
            UIUtils.hideLoading();
            this.isShowLoading = false;
        }
    }

    onErrorHandler(protoId: number, proto: any) {
        if (proto && proto.succ == ESUCC.FAIL) {
            switch (proto.code) {
                case ECODE.INVALID_REQUEST:
                    Log.d(`协议 ${protoId} >>>>无效请求`);
                    break;
                case ECODE.STOP_SERVER:
                    if (
                        User.instance.vistor == 1 ||
                        User.instance.isWhite ||
                        !!proto["white"]
                    ) {
                        return;
                    }
                    User.instance.stopServerInfo = {
                        succ: 1,
                        code: 1,
                        is_all: 1,
                        gameid: "",
                        starttime: proto["starttime"],
                        endtime: proto["endtime"],
                    };
                    Log.d(`协议 ${protoId} >>>> 停服中`);
                    break;
                default:
                    UIUtils.showError(protoId, proto.code);
                    break;
            }
        }
    }
}
