import { sys, game, native } from "cc";
import { JSB, PREVIEW } from "cc/env";
import { Eventer } from "../Eventer";
import { Singleton } from "../Singleton";
import { HotUpdate } from "./IHotUpdate";

class AssetsManager {
    constructor(name: string) {
        this.name = name;
    }

    /**  当前资源管理器的状态*/
    code: any = -1;
    /** 当前资源管理器的名称 */
    name: string = "";
    /** 当前资源管理器的实体 native.AssetsManager */
    manager: native.AssetsManager = null!;
}

const MAIN_PACK = "main";
const manifestRoot: string = `manifest/`;
const MANIFEST_NAME = "project.manifest";
const MANIFEST_PATHS = {
    packageUrl: "packageUrl",
    remoteManifestUrl: "remoteManifestUrl",
    remoteVersionUrl: "remoteVersionUrl"
};

/**
 *  热更新组件
 */
export class HotUpdateManager extends Singleton<HotUpdateManager>() {
    /** 本地存储热更新文件的路径 */
    private storagePath = "";
    /** 是否在热更新中或检测更新状态 */
    public updating = false;
    private platformId: string = '';
    private cdnUrl = '';
    /** 通用的热更新地址，当在子游戏或大厅未指定热更新地址时，都统一使用服务器传回来的默认全局更新地址 */
    public get commonHotUpdateUrl(): string {
        if (this.cdnUrl.length > 0) {
            return this.cdnUrl;
        } else {
            return this.projectManifest.packageUrl as string;
        }
    }

    /** 是否路过热更新 */
    public isSkipCheckUpdate = false;

    private _projectManifest: HotUpdate.Manifest | null = null;
    private get projectManifest(): HotUpdate.Manifest {
        if (JSB && !this._projectManifest) {
            let content = native.fileUtils.getStringFromFile(this.hallProjectMainfest);
            try {
                this._projectManifest = JSON.parse(content);
            } catch (err) {
                this._projectManifest = null;
                Log.w(`读取${this.hallProjectMainfest}失败`);
            }
        }
        return this._projectManifest as any;
    }

    /** 大厅本地的版本项目更新文件配置路径 */
    public get hallProjectMainfest() {
        return `${manifestRoot}project.manifest`;
    }
    /** 检测更新回调 */
    public checkCallback: ((code: HotUpdate.Code, state: HotUpdate.State) => void) | null = null;

    /** bundle版本信息 */
    public bundlesConfig: { [key: string]: HotUpdate.BundleConfig } = {};

    /** 资源管理器 */
    private assetsManagers: { [key: string]: AssetsManager } = {};

    public hotUpdateUrls: { [key: string]: string } = {};
    /** 热更新地址，为了方便后面当只更新一个游戏，或cdn服务器 */
    private getHotUpdateUrl(moduleName: string) {
        if (this.hotUpdateUrls[moduleName]) {
            return this.hotUpdateUrls[moduleName];
        } else {
            return this.commonHotUpdateUrl;
        }
    }

    /** 当前热更新的资源管理器 */
    private currentAssetsManager: AssetsManager = null!;
    /** 当前热更新的bundle */
    private curBundle: string = null!;

    /** 获取Bundle名 */
    public getBundleName(bundle: string) {
        return this.bundlesConfig[bundle];
    }

    /** 初始化参数 */
    public init(platformId: string, cdnUrl: string) {
        if (!sys.isNative) {
            return;
        }
        this.platformId = platformId;
        this.cdnUrl = cdnUrl;
    }

    /** 释放资源管理器，默认为hall 大厅资源管理器 */
    private destroyAssetsManager(name: string = MAIN_PACK) {
        if (this.assetsManagers[name]) {
            Log.d("destroyAssetsManager : " + name);
            this.currentAssetsManager = <any>null;
            delete this.assetsManagers[name];
        }
    }

    /** 获取资源管理器，默认为hall 大厅的资源管理器 */
    private getAssetsManager(name: string = MAIN_PACK) {
        if (this.assetsManagers[name]) {
            return this.assetsManagers[name];
        } else {
            //初始化资源管理器
            if (JSB) {
                let dir = this.platformId ? (this.platformId + "/") : "";
                this.storagePath = native.fileUtils.getWritablePath() + dir + name;
                Log.d(`Storage path for remote asset : ${this.storagePath}`);
                this.assetsManagers[name] = new AssetsManager(name);
                this.assetsManagers[name].manager = new native.AssetsManager(
                    name == MAIN_PACK ? `type.${MAIN_PACK}` : `type.${name}_`,
                    this.storagePath,
                    this.versionCompareHanle.bind(this)
                );
                //设置下载并发量
                this.assetsManagers[name].manager.setVerifyCallback(function (path, asset) {
                    let compressed = asset.compressed;
                    let expectedMD5 = asset.md5;
                    let relativePath = asset.path;
                    let size = asset.size;
                    if (compressed) {
                        Log.d(`Verification passed : ${relativePath}`);
                        return true;
                    } else {
                        Log.d(`Verification passed : ${relativePath} ( ${expectedMD5} )`);
                        return true;
                    }
                });
                Log.d(`Hot update is ready , please check or directly update.`);
            }
            return this.assetsManagers[name];
        }
    }

    /** 判断是否需要重新尝试下载之前下载失败的文件 */
    private isTryDownloadFailedAssets() {
        if (
            this.currentAssetsManager &&
            (this.currentAssetsManager.manager.getState() ==
                (HotUpdate.State.FAIL_TO_UPDATE as any) ||
                this.currentAssetsManager.code == HotUpdate.Code.ERROR_NO_LOCAL_MANIFEST ||
                this.currentAssetsManager.code == HotUpdate.Code.ERROR_DOWNLOAD_MANIFEST ||
                this.currentAssetsManager.code == HotUpdate.Code.ERROR_PARSE_MANIFEST)
        ) {
            return true;
        }
        return false;
    }

    /** 是否是预览或浏览器 */
    private get isBrowser() {
        return sys.platform == sys.Platform.WECHAT_GAME || PREVIEW || sys.isBrowser;
    }

    private isNeedUpdate(callback: (code: HotUpdate.Code, state: HotUpdate.State) => void) {
        if (this.isBrowser) {
            //预览及浏览器下，不需要有更新的操作
            this.updating = false;
            callback(HotUpdate.Code.ALREADY_UP_TO_DATE, HotUpdate.State.UP_TO_DATE);
            return false;
        } else {
            if (this.isSkipCheckUpdate) {
                Log.d("跳过热更新，直接使用本地资源代码");
                this.updating = false;
                callback(HotUpdate.Code.ALREADY_UP_TO_DATE, HotUpdate.State.UP_TO_DATE);
            } 
            return !this.isSkipCheckUpdate;
        }
    }

    /** 检测更新 */
    private _checkUpdate(callback: (code: HotUpdate.Code, state: HotUpdate.State) => void) {
        if (this.isNeedUpdate(callback)) {
            Log.d(`--checkUpdate--${this.updating}`);
            if (this.updating) {
                Log.d(`Checking or updating...`);
                callback(HotUpdate.Code.CHECKING, HotUpdate.State.PREDOWNLOAD_VERSION);
                return;
            }
            if (
                !this.currentAssetsManager.manager.getLocalManifest() ||
                !this.currentAssetsManager.manager.getLocalManifest().isLoaded()
            ) {
                Log.d(`Failed to load local manifest ....`);
                callback(HotUpdate.Code.ERROR_DOWNLOAD_MANIFEST, HotUpdate.State.FAIL_TO_UPDATE);
                return;
            }
            if (this.isTryDownloadFailedAssets()) {
                //已经更新失败，尝试获取更新下载失败的
                Log.d(`之前下载资源未完全下载完成，请尝试重新下载`);
                callback(HotUpdate.Code.UPDATE_FAILED, HotUpdate.State.TRY_DOWNLOAD_FAILED_ASSETS);
            } else {
                this.updating = true;
                if (this.currentAssetsManager.manager.getState() != HotUpdate.State.UPDATING) {
                    this.currentAssetsManager.manager.setEventCallback((event: any)=>{
                        this.checkCb(event, callback);
                    });
                    this.currentAssetsManager.manager.checkUpdate();
                }
            }
        }
    }

    downloadFailedAssets() {
        if (this.currentAssetsManager) {
            this.currentAssetsManager.manager.downloadFailedAssets();
        }
    }

    /** 检查主包是否需要更新 */
    private checkMainUpdate(callback: (code: HotUpdate.Code, state: HotUpdate.State) => void) {
        if (this.isNeedUpdate(callback)) {
            this.currentAssetsManager = this.getAssetsManager();
            this.currentAssetsManager.manager.loadLocalManifest(this.hallProjectMainfest);
            this._checkUpdate(callback);
        }
    }

    /**
     *  检测更新
     * @param callback 回调
     * @param bundle bundle,如果不传，则为对主包的检测
     */
    checkUpdate(callback: (code: HotUpdate.Code, state: HotUpdate.State) => void, bundle?: string) {
        if (typeof bundle == "string") {
            this.checkBundleUpdate(bundle, callback);
        } else {
            this.checkMainUpdate(callback);
        }
    }

    /**
     *  获取bundlemanifest url
     * @param bundle bundle
     * @returns manifest url
     */
    private getBundleManifest(bundle: string): string {
        let dir = this.platformId ? (this.platformId + "/") : "";
        let storagePath = native.fileUtils.getWritablePath() + dir + bundle;
        return `${storagePath}/${MANIFEST_NAME}`;
    }

    /**
     *  检测Bundle更新
     * @param bundle 子游戏名
     * @param callback 检测完成回调
     */
    private checkBundleUpdate(
        bundle: string,
        callback: (code: HotUpdate.Code, state: HotUpdate.State) => void
    ) {
        if (this.isNeedUpdate(callback)) {
            this.curBundle = bundle;
            this.currentAssetsManager = this.getAssetsManager(bundle);
            let manifestUrl = this.getBundleManifest(bundle);
            Log.d(`===checkBundleUpdate1==${manifestUrl}==${native.fileUtils.isFileExist(manifestUrl)}======`)
            //先检测本地是否已经存在子游戏版本控制文件
            if (native.fileUtils.isFileExist(manifestUrl)) {
                //存在版本控制文件
                let content = native.fileUtils.getStringFromFile(manifestUrl);
                let jsbGameManifest = new native.Manifest(content, this.storagePath);
                this.currentAssetsManager.manager.loadLocalManifest(jsbGameManifest, "");
                this.checkManifest(bundle, this.cdnUrl);
                this._checkUpdate(callback);
            } else {
                //不存在版本控制文件 ，生成一个初始版本
                if (this.updating) {
                    Log.d(`Checking or updating...`);
                    callback(HotUpdate.Code.CHECKING, HotUpdate.State.PREDOWNLOAD_VERSION);
                    return;
                }
                let gameManifest = this.createManifest(bundle);
                let gameManifestContent = JSON.stringify(gameManifest);
                let jsbGameManifest = new native.Manifest(gameManifestContent, this.storagePath);
                Log.d(`mainifest content : ${gameManifestContent}`);
                this.currentAssetsManager.manager.loadLocalManifest(jsbGameManifest, "");
                this._checkUpdate(callback);
            }
        }
    }

    private createManifest(bundle: string) {
        if(!sys.isNative) return;
        let version = '1.0.0';
        let packageUrl = this.getHotUpdateUrl(bundle);
        let platform = 'android';
        if(sys.os == sys.OS.IOS) {
            platform = 'ios';
        }
        let date = `?t=${Date.now()}`;
        let url = `${packageUrl}/gameupdate/${bundle}/${platform}/`
        let manifest = {
            packageUrl: url + version + "/",
            remoteManifestUrl: url + "project.manifest" + date,
            remoteVersionUrl: url + "version.manifest" + date,
            version: `${version}`,
            assets: {},
            searchPaths: [],
        }
        return manifest;
    }

    /** 检测更新 */
    private checkCb(event: any, callback: (code: HotUpdate.Code, state: HotUpdate.State) => void) {
        if (!this.currentAssetsManager) {
            Log.w(`checkCb热更新管理器未初始化`);
            return;
        }
        //这里不能置空，下载manifest文件也会回调过来
        //存储当前的状态，当下载版本文件失败时，state的状态与下载非版本文件是一样的状态
        this.currentAssetsManager.code = event.getEventCode();
        Log.d(
            `checkCb event code : ${event.getEventCode()} state : ${this.currentAssetsManager.manager.getState()}`
        );
        switch (event.getEventCode()) {
            case HotUpdate.Code.ERROR_NO_LOCAL_MANIFEST:
                Log.d(`No local manifest file found, hot update skipped.`);
                break;
            case HotUpdate.Code.ERROR_DOWNLOAD_MANIFEST:
            case HotUpdate.Code.ERROR_PARSE_MANIFEST:
                Log.d(`Fail to download manifest file, hot update skipped.`);
                break;
            case HotUpdate.Code.ALREADY_UP_TO_DATE:
                Log.d(`Already up to date with the latest remote version.`);
                break;
            case HotUpdate.Code.NEW_VERSION_FOUND:
                Log.d(`New version found, please try to update.`);
                break;
            case HotUpdate.Code.UPDATE_FINISHED:
                Log.d(`New version found, please try to update.`);
                break;
            default:
                return;
        }

        this.updating = false;
        //如果正在下载更新文件，先下载更新文件比较完成后，再回调
        if (
            callback &&
            this.currentAssetsManager.manager.getState() !=
                (HotUpdate.State.DOWNLOADING_VERSION)
        ) {
            callback(
                event.getEventCode(),
                this.currentAssetsManager.manager.getState() as any
            );
        }
    }

    /** 执行热更新*/
    hotUpdate() {
        if (!this.currentAssetsManager) {
            Log.w(`hotUpdate热更新管理器未初始化`);
            return;
        }
        let name = this.currentAssetsManager.name;
        Log.d(`即将热更新模块为:${name} , updating : ${this.updating}`);
        if (!this.updating) {
            Log.d(`执行更新 ${name} `);
            this.currentAssetsManager.manager.setEventCallback((event: any)=>{
                this.updateCb(event, name);
            });
            this.currentAssetsManager.manager.update();
        }
    }

    /** 热更新回调 */
    private updateCb(event: any, bundleName: string) {
        if (!this.currentAssetsManager) {
            Log.w(`updateCb热更新管理器未初始化`);
            return;
        }
        Log.d(`===updateCb===${this.currentAssetsManager.name}=${bundleName}===`)
        if (this.currentAssetsManager.name != bundleName) {
            Log.w(`updateCb 不是同一个bundleName`);
            return;
        }
        var isUpdateFinished = false;
        var failed = false;
        Log.d(
            `--update cb code : ${event.getEventCode()} state : ${this.currentAssetsManager.manager.getState()}`
        );
        //存储当前的状态，当下载版本文件失败时，state的状态与下载非版本文件是一样的状态
        this.currentAssetsManager.code = event.getEventCode();
        switch (event.getEventCode()) {
            case HotUpdate.Code.ERROR_NO_LOCAL_MANIFEST:
                Log.d(`No local manifest file found, hot update skipped.`);
                failed = true;
                break;
            case HotUpdate.Code.UPDATE_PROGRESSION:
                break;
            case HotUpdate.Code.ERROR_DOWNLOAD_MANIFEST:
            case HotUpdate.Code.ERROR_PARSE_MANIFEST:
                Log.d(`Fail to download manifest file, hot update skipped.`);
                failed = true;
                break;
            case HotUpdate.Code.ALREADY_UP_TO_DATE:
                Log.d(`Already up to date with the latest remote version.`);
                failed = true;
                break;
            case HotUpdate.Code.UPDATE_FINISHED:
                Log.d(`Update finished. ${event.getMessage()}`);
                isUpdateFinished = true;
                this.updating = false;
                break;
            case HotUpdate.Code.UPDATE_FAILED:
                Log.d(`Update failed. ${event.getMessage()}`);
                this.updating = false;
                break;
            case HotUpdate.Code.ERROR_UPDATING:
                Log.d(`Asset update error: ${event.getAssetId()} , ${event.getMessage()}`);
                failed = true;
                break;
            case HotUpdate.Code.ERROR_DECOMPRESS:
                Log.d(`${event.getMessage()}`);
                failed = true;
                break;
            default:
                break;
        }
        if (failed) {
            this.currentAssetsManager.manager.setEventCallback(null as any);
            this.updating = false;
        }

        if (isUpdateFinished) {
            //下载完成,需要重新设置搜索路径，添加下载路径
            var searchPaths: string[] = native.fileUtils.getSearchPaths();
            var newPaths: string[] = this.currentAssetsManager.manager
                .getLocalManifest()
                .getSearchPaths();
            Log.d(JSON.stringify(newPaths));
            Array.prototype.unshift.apply(searchPaths, newPaths);

            //这里做一个搜索路径去重处理
            let obj: any = {};
            for (let i = 0; i < searchPaths.length; i++) {
                obj[searchPaths[i]] = true;
            }
            searchPaths = Object.keys(obj);
            sys.localStorage.setItem("HotUpdateSearchPaths", JSON.stringify(searchPaths));
            native.fileUtils.setSearchPaths(searchPaths);
        }

        let state = this.currentAssetsManager.manager.getState();
        if (this.currentAssetsManager.name == MAIN_PACK) {
            if (isUpdateFinished) {
                this.currentAssetsManager.manager.setEventCallback(null as any);
                //下载数量大于0，才有必要进入重启，在如下这种情况下，并不会发生下载
                //当只提升了版本号，而并未对代码进行修改时，此时的只下载了一个project.manifest文件，
                //不需要对游戏进行重启的操作
                if (event.getDownloadedFiles() > 0) {
                    game.restart();
                }
                //下载完成 删除资源管理器
                this.destroyAssetsManager(this.currentAssetsManager.name);
            }
        } else {
            //子游戏更新
            if (isUpdateFinished) {
                Log.d(
                    `${this.currentAssetsManager.name} 下载资源数 : ${event.getDownloadedFiles()}`
                );
                //下载完成 删除资源管理器
                this.destroyAssetsManager(this.currentAssetsManager.name);
            }
        }

        let info: HotUpdate.DownLoadInfo = {
            downloadedBytes: event.getDownloadedBytes(),
            totalBytes: event.getTotalBytes(),
            downloadedFiles: event.getDownloadedFiles(),
            totalFiles: event.getTotalFiles(),
            percent: event.getPercent(),
            percentByFile: event.getPercentByFile(),
            code: event.getEventCode(),
            state: state as any,
            needRestart: isUpdateFinished,
        };
        let eventName = this.curBundle ? HotUpdate.Event.HOTUPDATE_DOWNLOAD + `_${this.curBundle}` : HotUpdate.Event.HOTUPDATE_DOWNLOAD;
        Eventer.getInstance().emit(eventName, info);

        // Log.d(
        //     `update cb  failed : ${failed}  , need restart : ${isUpdateFinished} , updating : ${this.updating}`
        // );
    }

    private versionCompareHanle(versionA: string, versionB: string) {
        Log.d(`JS Custom Version Compare : version A is ${versionA} , version B is ${versionB}`);
        let vA = versionA.split(".");
        let vB = versionB.split(".");
        Log.d(`version A ${vA} , version B ${vB}`);
        for (let i = 0; i < vA.length && i < vB.length; ++i) {
            let a = parseInt(vA[i]);
            let b = parseInt(vB[i]);
            if (a === b) {
                continue;
            } else {
                //版本不同就更新
                return -1;
                //大于当前版本才更新
                // return a - b;
            }
        }
        if (vB.length > vA.length) {
            return -1;
        }
        return 0;
    }

    getVersion() {
        return this.currentAssetsManager?.manager?.getLocalManifest()?.getVersion();
    }

    /**
     * 检查project.manifest
     * 如果cdn地址不一样，重定向cdn地址
     * @param bundle
     * @param cdnUrl
     */
    checkManifest(bundle: string, cdnUrl: string) {
        if (!sys.isNative || !bundle)
            return;
        if (!cdnUrl || cdnUrl === "") return;
        Log.d(`=checkManifest game==`);
        let jsonData = this.getStorageManifestData(bundle);
        if (!jsonData) return;
        let packageUrl = jsonData[MANIFEST_PATHS.packageUrl];
        if (!packageUrl) return;
        if (String(packageUrl).indexOf(cdnUrl) == -1) {
            for (let i in MANIFEST_PATHS) {
                let path = jsonData[i] as string;
                if (!path) {
                    Log.w(`No manifest path=${path} found! `);
                    return;
                } else {
                    let pos1 = this.findPos(path, "/", 2);
                    path = path.replace(path.substring(0, pos1), cdnUrl);
                    let pos2 = this.findPos(path, "/", 3);
                    let pos3 = this.findPos(path, "/", 4);
                    if (pos3 > pos2) {
                        path = path.replace(
                            path.substring(pos2 + 1, pos3),
                            bundle
                        );
                        jsonData[i] = path;
                    } else {
                        Log.w(`manifest replace url error=${i}! `);
                        return;
                    }
                    Log.d(`=manifest replace success!=${i}=${path}==`);
                }
            }
            jsonData['version'] = '1.0.0';
            let afterString = JSON.stringify(jsonData);
            let manifest = this.assetsManagers[bundle].manager.getLocalManifest();
            manifest.parseJSONString(afterString, manifest.getManifestRoot());
        }
    }

    /**
     * 获取缓冲区manifest
     * @returns 
     */
    getStorageManifestData(bundle: string) {
        let fileName = this.getBundleManifest(bundle);
        let url = '';
        if (native.fileUtils.isFileExist(fileName)) {
            url = fileName;
        } 
        if (url == '') return;
        let loadManifest = native.fileUtils.getStringFromFile(url);
        let jsonData = JSON.parse(loadManifest);
        return jsonData;
    }

    /**
     * 查找子串出现第N次的位置
     * @param str
     * @param reg
     * @param n
     * @returns
     */
    findPos(str: string, reg: string, n: number) {
        var x = str.indexOf(reg);
        for (var i = 0; i < n; i++) {
            x = str.indexOf(reg, x + 1);
        }
        return x;
    }
}
