    // }
    // public get isPswShow(): boolean {
    //     return this._isPswShow;
    // }

    @property({ displayName: "eye btn", type: Node })
    public eyeBtn: Node = null!;

    @property({ displayName: "editBox", type: Node })
    public editBox: Node = null!;

    start() {
        // [3]
        if (!EDITOR) {
            this.bindEvents();
            this.editBox.getComponent(EditBox)!.placeholderLabel!.overflow = 2;
        } else {
        }
    }
    bindEvents() {
        if (!this.eyeBtn) return;
        this.eyeBtn.on(Node.EventType.TOUCH_END, () => {
            let eyeOpenBtn = this.eyeBtn.getChildByName("eye_open")!;
            let eyeCloseBtn = this.eyeBtn.getChildByName("eye_close")!;
            if (eyeOpenBtn?.active == true) {
                // eyeOpenBtn.active = false;
                // eyeCloseBtn.active = true;
                // this.setPasswordVisible(false);
                this.doSetPswEyedOpen(true);
            } else {
                // eyeOpenBtn.active = true;
                // eyeCloseBtn.active = false;
                // this.setPasswordVisible(true);
                this.doSetPswEyedOpen(false);
            }
        });
    }

    /**
     * 在密码类型下，设置密码是否可见
     * @param isOpen
     */
    public doSetPswEyedOpen(isOpen: boolean) {
        if (!this.eyeBtn) return;

        let eyeOpenBtn = this.eyeBtn.getChildByName("eye_open")!;
        let eyeCloseBtn = this.eyeBtn.getChildByName("eye_close")!;
        if (isOpen == true) {
            eyeOpenBtn.active = false;
            eyeCloseBtn.active = true;
            this.setPasswordVisible(false);
        } else {
            eyeOpenBtn.active = true;
            eyeCloseBtn.active = false;
            this.setPasswordVisible(true);
        }
    }

    private setPasswordVisible(isVisible: boolean) {
        if (isVisible == true) {
            this.editBox.getComponent(EditBox)!.inputFlag =
                EditBox.InputFlag.DEFAULT;
        } else {
            this.editBox.getComponent(EditBox)!.inputFlag =
                EditBox.InputFlag.PASSWORD;
        }
    }

    private setEyeIsVisible(isVisible: boolean) {
        if (!this.eyeBtn) return;
        this.eyeBtn.active = isVisible;
        let editBoxWidth = 0;
        if (isVisible == true) {
            editBoxWidth =
                this.node.getComponent(UITransform)!.width -
                this.eyeBtn.getComponent(UITransform)!.width -
                30;
        } else {
            editBoxWidth = this.node.getComponent(UITransform)!.width - 30;
        }
        this.editBox.getComponent(UITransform)!.width = editBoxWidth;
    }
    private setIsPassword(isPassword: boolean) {
        if (isPassword == true) {
            this.editBox.getComponent(EditBox)!.inputFlag =
                EditBox.InputFlag.PASSWORD;
        } else {
            this.editBox.getComponent(EditBox)!.inputFlag =
                EditBox.InputFlag.DEFAULT;
        }
        //重新刷新查看密码
        this._lookPswType = isPassword;
        this.setEyeIsVisible(isPassword);
    }
    private setIsEditable(isEditable: boolean) {
        this.editBox.getComponent(EditBox)!.enabled = isEditable;
    }
    private setPlaceHolder(str: String) {
        this.editBox.getComponent(EditBox)!.placeholderLabel!.string =
            str.toString();
    }
    private setEditBoxStr(str: String) {
        this.editBox.getComponent(EditBox)!.string = str.toString();
    }
    public get string(): string {
        return this.editBox.getComponent(EditBox)!.string.trim();
    }
    public set string(str: string) {
        this.editBox.getComponent(EditBox)!.string = str;
    }
    // update (deltaTime: number) {
