import {
    _decorator,
    Component,
    Node,
    __private,
    NodeEventType,
    EventTouch,
    UITransform, Enum, CCFloat, UIOpacity, Tween, tween
} from "cc";
import { SoundDefine, SoundNameEnum } from "../../../common/define/ResDefine";
import LogUtil from "../../../common/utils/LogUtil";
import AudioManager from "../../manager/AudioManager";
const { ccclass, property, menu, disallowMultiple } = _decorator;

/** 按钮状态枚举 */
enum ButtonState {
    NORMAL = "normal",
    HOVER = "hover",
    PRESSED = "pressed",
    DISABLED = "disabled",
    SELECT = "select",
}

@ccclass("UIButtonState")
@menu("ui/basic_ui/UIButtonState")
@disallowMultiple(true)
/** 
 * 状态按钮 <br/>
 * 不要自行监听事件，统一使用 
 * touchBeganFun(target), 
 * touchMoveFun(target), 
 * touchEndedFun(target), 
 * touchCancelFun(target)
 * 按钮数据： buttonData
 * 按钮cd：btnCD
 * @author ice
*/
export class UIButtonState extends Component {

    @property({ displayName: "btnCD", type: CCFloat, tooltip: '按钮点击后的冷却时间，单位：秒' })
    public btnCD: number = 0.5;
    /**
     * @en
     * Normal state node.
     * @zh
     * 普通状态下按钮所显示的 Node
     */
    @property
    protected _normalNode: Node | null = null;
    @property({ displayName: "normalNode", type: Node, tooltip: "普通状态的节点", })
    get normalNode() {
        return this._normalNode;
    }
    set normalNode(value: Node | null) {
        this._normalNode = value;
        this.updateState();
    }
    /**
     * @en
     * Hover state Node.
     * @zh
     * 悬停状态下按钮所显示的 Node
     */
    @property
    protected _hoverNode: Node | null = null;
    @property({
        displayName: "hoverNode",
        type: Node,
        tooltip: "悬停状态下按钮所显示的节点",
    })
    get hoverNode() {
        return this._hoverNode;
    }
    set hoverNode(value: Node | null) {
        this._hoverNode = value;
    }

    /**
     * @en
     * Pressed state Node.
     * @zh
     * 按下状态时按钮所显示的 Node
     */
    @property
    protected _pressedNode: Node | null = null;
    @property({
        displayName: "pressedNode",
        type: Node,
        tooltip: "按下状态时按钮所显示的节点",
    })
    get pressedNode() {
        return this._pressedNode;
    }
    set pressedNode(value: Node | null) {
        this._pressedNode = value;
    }

    @property
    protected _disabledNode: Node | null = null;
    @property({
        displayName: "disabledNode",
        type: Node,
        tooltip: "禁用状态下按钮所显示的节点",
    })
    get disabledNode() {
        return this._disabledNode;
    }
    set disabledNode(value: Node | null) {
        this._disabledNode = value;
    }

    @property
    protected _selectNode: Node | null = null;
    @property({
        displayName: "selectNode",
        type: Node,
        tooltip: "选中状态下按钮所显示的节点",
    })
    get selectNode() {
        return this._selectNode;
    }
    set selectNode(value: Node | null) {
        this._selectNode = value;
    }

    private _soundNameStr: string;
    @property
    private _soundName: SoundNameEnum = SoundNameEnum.sound_click;
    @property({
        type: Enum(SoundNameEnum),
        tooltip: '按钮声音'
    })
    set soundName(val: SoundNameEnum) {
        this._soundName = val;
        if (val == SoundNameEnum.no_sound) {
            this._soundNameStr = null;
        }
        else {
            this._soundNameStr = SoundNameEnum[this._soundName];
        }
    }
    get soundName() {
        return this._soundName;
    }

    @property({ displayName: 'opacityCD', type: CCFloat, tooltip: '按钮点击后，等待时间后进入透明状态' })
    public opacityCD: number = 1.5;
    /**
     * @en
     * Opacity Function Switch
     * @zh
     * 按钮点击后，进入透明状态功能开关
     */
    @property
    public opacityFuncSwi: boolean = false;

    @property
    public opacityHigh: number = 255;
    @property
    public opacityLow: number = 100;

    public touchBeganFun: Function;
    public touchMoveFun: Function;
    public touchEndedFun: Function;
    public touchCancelFun: Function;

    protected _state: ButtonState = ButtonState.NORMAL;
    protected _select: boolean = false;
    public get select(): boolean {
        return this._select;
    }
    public set select(val: boolean) {
        this._select = val;
        if (val == true) {
            this._state = ButtonState.SELECT;
        }
        else {
            this._state = ButtonState.NORMAL;
        }
        this.updateState();
    }
    protected _interactable = true;
    private _pressed = false;
    // private _hovered = false;

    private _isInCD: boolean = false;
    private _cdTime: number = 0;

    private _opacityCDTime: number = 0;

    protected onLoad(): void {
        // protected start(): void{
        if (this._soundName == SoundNameEnum.no_sound) {
            this._soundNameStr = null;
        }
        else {
            this._soundNameStr = SoundNameEnum[this._soundName];
        }
        this.updateState();
    }

    update(deltaTime: number) {
        if (this._isInCD) {
            this._cdTime += deltaTime;
            if (this._cdTime >= this.btnCD) {
                this._cdTime = 0;
                this._isInCD = false;
            }
        }

        this.refreshOpacity(deltaTime);
    }

    private refreshOpacity(deltaTime: number) {
        //透明度
        if (!this.opacityFuncSwi)
            return;

        if (this._pressed)
            return;

        if (this._opacityCDTime <= 0)
            return;

        let com = this.getComponent(UIOpacity);
        if (!com)
            return;

        this._opacityCDTime -= deltaTime;
        if (this._opacityCDTime <= 0) {
            Tween.stopAllByTarget(com);
            tween(com)
                .to(0.5, { opacity: this.opacityLow })
                .start();
        }
    }

    protected updateState() {
        this.updateSpriteTransition(this._state);
    }

    protected updateSpriteTransition(state: string) {
        this.hideAllState();
        const myNode = this[`${state}Node`];
        if (myNode) {
            myNode.active = true;
        }
        else if (state == ButtonState.DISABLED || state == ButtonState.SELECT) {
            if (this.pressedNode) {
                this.pressedNode.active = true;
            }
            else {
                this.normalNode.active = true;
            }
        }
        else {
            this.normalNode.active = true;
        }
    }

    private hideAllState(): void {
        if (this.normalNode) {
            this.normalNode.active = false;
        }
        if (this.hoverNode) {
            this.hoverNode.active = false;
        }
        if (this.pressedNode) {
            this.pressedNode.active = false;
        }
        if (this.disabledNode) {
            this.disabledNode.active = false;
        }
        if (this.selectNode) {
            this.selectNode.active = false;
        }
    }

    public reset() {
        this.opacityFuncSwi = true;
        if (this.opacityFuncSwi)
            this.getComponent(UIOpacity).opacity = this.opacityLow;
        else
            this.getComponent(UIOpacity).opacity = this.opacityHigh;
    }

    public onEnable() {
        this.addToStage();

        let com = this.getComponent(UIOpacity);
        if (!com)
            return;

        if (this.opacityFuncSwi)
            this.getComponent(UIOpacity).opacity = this.opacityLow;
        else
            this.getComponent(UIOpacity).opacity = this.opacityHigh;
    }

    public onDisable() {
        this.removeFromStage();
    }

    // get enabled(): boolean;
    public setEnabled(value: boolean) {
        // this._enabled = value;
        this.enabled = value;
        if (value == false) {
            this._state = ButtonState.DISABLED;
        }
        else if (this._state == ButtonState.DISABLED) {
            this._state = ButtonState.NORMAL;
        }
        this.updateState();
    }

    protected onTouchBegan(event?: EventTouch) {
        if (!this._interactable || !this.enabledInHierarchy) {
            return;
        }
        this._pressed = true;
        this._state = ButtonState.PRESSED;
        this.updateState();
        if (event) {
            event.propagationStopped = true;
        }
        if (this._isInCD) {
            LogUtil.log("按钮在cd中。。。");
            return;
        }
        if (this.touchBeganFun) {
            this.touchBeganFun(this, event);
        }
        if (this.opacityFuncSwi) {
            this._opacityCDTime = this.opacityCD;
            let com = this.getComponent(UIOpacity);
            Tween.stopAllByTarget(com);
            if (com) {
                com.opacity = this.opacityHigh;
            }
        }
    }

    protected onTouchMove(event?: EventTouch) {
        if (!this._interactable || !this.enabledInHierarchy || !this._pressed) {
            return;
        }
        if (!event) {
            return;
        }
        let touch = event.touch;
        if (!touch) {
            return;
        }
        let hit = this.node
            .getComponent(UITransform)
            .hitTest(touch.getLocation());
        if (hit) {
            this._state = ButtonState.PRESSED;
        } else {
            this._state = ButtonState.NORMAL;
        }
        this.updateState();
        if (event) {
            event.propagationStopped = true;
        }
        if (this._isInCD) {
            LogUtil.log("按钮在cd中。。。");
            return;
        }
        if (this.touchMoveFun) {
            this.touchMoveFun(this, event);
        }
    }

    protected onTouchEnded(event?: EventTouch) {
        if (!this._interactable || !this.enabledInHierarchy) {
            return;
        }
        this._pressed = false;
        this._state = ButtonState.NORMAL;
        this.updateState();

        if (this._soundNameStr && this._soundNameStr.length > 0) {
            AudioManager.Instance().playEffect(SoundDefine[this._soundNameStr]);
        }
        if (event) {
            event.propagationStopped = true;
        }

        if (this._isInCD) {
            LogUtil.log("按钮在cd中。。。");
            return;
        }
        if (this.touchEndedFun) {
            this.touchEndedFun(this, event);
        }
        this._cdTime = 0;
        this._isInCD = true;
    }

    protected onTouchCancel(event?: EventTouch) {
        if (!this._interactable || !this.enabledInHierarchy) {
            return;
        }

        this._pressed = false;
        this._state = ButtonState.NORMAL;
        this.updateState();
        if (this.touchCancelFun) {
            this.touchCancelFun(this, event);
        }
    }

    protected addToStage() {
        this.node.on(NodeEventType.TOUCH_START, this.onTouchBegan, this);
        this.node.on(NodeEventType.TOUCH_MOVE, this.onTouchMove, this);
        this.node.on(NodeEventType.TOUCH_END, this.onTouchEnded, this);
        this.node.on(NodeEventType.TOUCH_CANCEL, this.onTouchCancel, this);

        // this.node.on(NodeEventType.MOUSE_ENTER, this.onMouseMoveIn, this);
        // this.node.on(NodeEventType.MOUSE_LEAVE, this.onMouseMoveOut, this);

    }

    protected removeFromStage() {
        this.node.off(NodeEventType.TOUCH_START, this.onTouchBegan, this);
        this.node.off(NodeEventType.TOUCH_MOVE, this.onTouchMove, this);
        this.node.off(NodeEventType.TOUCH_END, this.onTouchEnded, this);
        this.node.off(NodeEventType.TOUCH_CANCEL, this.onTouchCancel, this);

        // this.node.off(NodeEventType.MOUSE_ENTER, this.onMouseMoveIn, this);
        // this.node.off(NodeEventType.MOUSE_LEAVE, this.onMouseMoveOut, this);
    }
}
