import {
    CCString,
    Component,
    Size,
    Sprite,
    SpriteFrame,
    UITransform,
    _decorator,
} from "cc";
import { EDITOR } from "cc/env";
import { Global } from "../../main/Global";
import LogUtil from "../../common/utils/LogUtil";
import { ResManager } from "../manager/ResManager";
import { ResDefine } from "../../common/define/ResDefine";
import { Macro } from "../../common/define/HotUpdateDefine";
import { ELanguage_Type } from "../../common/define/EnumDefine";

const { ccclass, property, menu } = _decorator;

@ccclass("LanguageSprite")
@menu("ui/language/LanguageSprite")
export class LanguageSprite extends Component {
    @property({ serializable: true })
    private _imageStr: string = "";
    @property({ type: CCString, serializable: true })
    get imageStr(): string {
        return this._imageStr || "";
    }
    set imageStr(value: string) {
        this._imageStr = value;
        if (!EDITOR) {
            this.updateSprite();
        }
    }

    @property({
        tooltip: "是否设置为图片原始资源大小",
    })
    private isRawSize: boolean = true;
    private languageTypeArr: Array<ELanguage_Type> = []; //如果语言配置为空的情况下，默认全语种

    private changeCb: Function = null!;

    start() {
        this.updateSprite();
    }
    public setChangeCb(cb: Function) {
        this.changeCb = cb;
    }

    /** 更新语言 */
    language() {
        this.updateSprite();
    }
    /**
     * 设置语言种类，如果语言配置为空的情况下，默认全语种
     * @param languageTypeArr
     */
    public setLanguageTypeArr(languageTypeArr: Array<ELanguage_Type> = []) {
        this.languageTypeArr = languageTypeArr;
    }

    private updateSprite() {
        let _language = "";
        _language = Global.language;
        if (this.languageTypeArr.length > 0) {
            if (this.languageTypeArr.indexOf(Global.language) == -1) {
                _language = ELanguage_Type.EN;
            }
        }

        let path = `${ResDefine.LANGUAGE_SPRITE_URL}${_language}/${this._imageStr}/spriteFrame`;

        ResManager.Instance().load(
            Macro.BUNDLE_RESOURCES,
            path,
            SpriteFrame,
            () => { },
            (cache: any) => {
                let res: SpriteFrame | null = cache.data;
                if (!res) {
                    LogUtil.warn("[LanguageSprite] 资源不存在 " + path);
                } else {
                    LogUtil.debug("language sprite:", this);
                    if (!this.node) {
                        return;
                    }
                    let spcomp: Sprite = this.getComponent(Sprite)!;

                    spcomp.spriteFrame = res;

                    /** 修改节点为原始图片资源大小 */
                    if (this.isRawSize) {
                        //@ts-ignore
                        let rawSize = res._originalSize as Size;
                        spcomp
                            .getComponent(UITransform)
                            ?.setContentSize(rawSize);
                    }
                    if (this.changeCb) {
                        this.changeCb();
                    }
                }
            }
        );
    }
}
