import { UIView, UIZIndex } from "./../../framework/ui/UIView";
import { _decorator, Node, Label } from "cc";
import { LanguageSprite } from "../../framework/language/LanguageSprite";
import { ELanguage_Type } from "../../common/define/EnumDefine";
const { ccclass, property } = _decorator;

/**提示框参数 */
export type NoticeParam = {
    /**显示内容 */
    content: string;
    /**二级黄色文字显示内容 */
    content2?: string;
    /**普通标题文字 */
    txtTitle?: string;
    /**多语言图片标题名字 */
    spriteTitleName?: string;
    /**多语言图片标题语言种类，默认全语言 */
    spriteTitleTypes?: Array<ELanguage_Type>;
    /**确定回调 */
    okFunc?: Function;
    /**取消回调 */
    cancelFunc?: Function;
    /**确定按钮内容 */
    okName?: string;
    /**取消按钮内容 */
    cancelName?: string;
    /**是否是单个按钮 */
    singleBtn?: boolean;
};

@ccclass("UIAlert")
export class UIAlert extends UIView {
    @property({ displayName: "确定按钮", type: [Node] })
    confirmBtns: Array<Node> = [];
    @property({ displayName: "取消按钮", type: [Node] })
    cancelBtns: Array<Node> = [];
    @property({ displayName: "内容labels", type: [Label] })
    contentLabels: Array<Label> = [];
    @property({ displayName: "内容label2", type: Label })
    contentLabel2: Label = null!;
    @property({ displayName: "普通标题label", type: Label })
    normalTitle: Label = null!;
    @property({ displayName: "图片标题label", type: LanguageSprite })
    spriteTitle: LanguageSprite = null!;
    @property({ displayName: "无标题面板", type: Node })
    noTitlePanel: Node = null!;
    @property({ displayName: "有标题面板", type: Node })
    titlePanel: Node = null!;
    @property({ displayName: "多语言图片标题", type: Node })
    languageSpriteTitle: Node = null!;

    param: NoticeParam = null;

    start() {
        this.bindEvents();
    }
    onOpen(...args): void {
        // AudioManager.Instance().playEffect(SoundDefine.sound_error);
        this.node.zIndex = UIZIndex.notice;

        if (args != null && args[0] != null) {
            this.param = args[0] as NoticeParam;
        }
        this.refresh();
    }

    refresh() {
        if (!this.param || !this.param.content || this.param.content == "")
            return;

        let isTitlePanel: boolean = false;
        if (this.param.txtTitle || this.param.spriteTitleName) {
            isTitlePanel = true;
        }
        this.noTitlePanel.active = !isTitlePanel;
        this.titlePanel.active = isTitlePanel;

        for (let i = 0; i < this.contentLabels.length; i++) {
            this.contentLabels[i].string = this.param.content;
        }

        this.contentLabel2.node.active = false;
        if (this.param.content2) {
            this.contentLabel2.node.active = true;
            this.contentLabel2.string = this.param.content2;
        }

        if (this.param.okName && this.param.okName != "") {
            for (let i = 0; i < this.confirmBtns.length; i++) {
                this.confirmBtns[i]
                    .getChildByName("Label")!
                    .getComponent(Label)!.string = this.param.okName;
            }
        }
        if (this.param.cancelName && this.param.cancelName != "") {

            for (let i = 0; i < this.cancelBtns.length; i++) {
                this.cancelBtns[i]
                    .getChildByName("Label")!
                    .getComponent(Label)!.string = this.param.cancelName;
            }
        }

        if (this.param.singleBtn) {
            for (let i = 0; i < this.cancelBtns.length; i++) {
                this.cancelBtns[i].active = false;
            }
        } else {
            for (let i = 0; i < this.cancelBtns.length; i++) {
                this.cancelBtns[i].active = true;
            }
        }

        this.normalTitle.node.active = false;
        this.spriteTitle.node.active = false;
        if (this.param.txtTitle) {
            this.normalTitle.node.active = true;
            this.normalTitle.string = this.param.txtTitle;
        }

        if (this.param.spriteTitleName) {
            this.spriteTitle.node.active = true;
            this.spriteTitle.imageStr = this.param.spriteTitleName;
            if (this.param.spriteTitleTypes) {
                this.spriteTitle.setLanguageTypeArr(
                    this.param.spriteTitleTypes
                );
            }
        }
    }

    bindEvents() {
        for (let i = 0; i < this.confirmBtns.length; i++) {
            this.confirmBtns[i].on(
                Node.EventType.TOUCH_END,
                () => {
                    if (this.param.okFunc) {
                        this.param.okFunc();
                    }
                    this.close();
                },
                this
            );
        }

        for (let i = 0; i < this.cancelBtns.length; i++) {
            this.cancelBtns[i].on(
                Node.EventType.TOUCH_END,
                () => {
                    if (this.param.cancelFunc) {
                        this.param.cancelFunc();
                    }
                    this.close();
                },
                this
            );
        }
    }
}
