import { Node, _decorator, Component, isValid, UIOpacity, UITransform, view, Sprite, color } from "cc";
import { UIManager } from "./UIManager";
import { UIView } from "./UIView";

const { ccclass, menu } = _decorator;

/**
 * UIMask 界面遮罩
 */
@ccclass
@menu('ui/common/UIMask')
export class UIMask extends Component {

    addTouch(uiView: UIView) {
        if (this.node?.isValid && uiView.quickClose) {
            this.node.targetOff(Node.EventType.TOUCH_START);
            this.node.on(
                Node.EventType.TOUCH_START,
                () => {
                    UIManager.getInstance().close(uiView);
                },
                this
            );
        }
    }

    addMask(uiView: UIView) {
        if (this.node?.isValid) {
            if (this.node.active && this.node.zIndex > 0
                && (uiView.node.zIndex == undefined || uiView.node.zIndex < this.node.zIndex)) {
                return;
            }
            // this.node.getComponent(Sprite)!.color = color(0, 0, 0, 170);
            this.resetIndex(uiView);
            this.addTouch(uiView);
            this.node.getComponent(UITransform)!.setContentSize(view.getVisibleSize());
        }
    }

    removeMask() {
        let uiView = UIManager.getInstance().checkMaskView();
        if (this.node?.isValid) {
            if (uiView && isValid(uiView.node) && uiView.node.active && uiView.isMask) {
                this.resetIndex(uiView);
            } else {
                this.node.getComponent(Sprite)!.color = color(0, 0, 0, 1);
                this.node.active = false;
            }
        }
    }

    private resetIndex(uiView: UIView) {
        this.node.getComponent(Sprite)!.color = color(0, 0, 0, 170);
        this.node.active = true;
        this.node.zIndex = uiView.node.zIndex;
        let index = uiView.node.getSiblingIndex();
        // this.node.setSiblingIndex(index);
        // uiView.node.setSiblingIndex(index + 1); 
        UIManager.getInstance().setSiblingIndex(this.node, index);
        UIManager.getInstance().setSiblingIndex(uiView.node, index + 1);

        this.addTouch(uiView);
    }
}