import { sys } from "cc";

export default class DStorage {
	static set(key: string, value: any) {
		sys.localStorage.setItem(key, JSON.stringify(value));
	}

	static get(key: string) {
		let res = sys.localStorage.getItem(key);
		let retString = null;
		if (res && res != "undefined" && res != undefined) {
			try {
				retString = JSON.parse(res);
			} catch (error) {
				error(error);
			}
		}
		return retString;
	}

	static remove(key: string) {
		sys.localStorage.removeItem(key);
	}

	static getItem<T>(key: string, defaultValue: T): T {
        let value = localStorage.getItem(key);
        return value == undefined ? defaultValue : <T>(<any>value);
    }

    static getNum(key: string, defaultValue: number): number {
        let value = localStorage.getItem(key);
        if (value == undefined || value == "") {
            return defaultValue;
        } else {
            return Number(value);
        }
    }

    static setItem<T>(key: string, value: T) {
        Log.d("setitem:key:" + key + ",value:" + value);
        localStorage.setItem(key, String(value));
    }

    static removeItem(key: string) {
        localStorage.removeItem(key);
    }

    static getObj(key: string, defaultValue: object) {
        let value = localStorage.getItem(key);
        if (value == undefined || value == "") {
            return defaultValue;
        } else {
            return JSON.parse(value);
        }
    }

    static setObj(key: string, value: object) {
        let str = JSON.stringify(value);
        localStorage.setItem(key, str);
    }
}
