import ResourceLoader from "../ResourceLoader";

export abstract class Entry {
    static bundle = "";
    /** 是否是主包入口，只能有一个主包入口 */
    isMain = false;
    /** 当前bundle名,由管理器指定 */
    bundle: string = "";

    /** 模块资源加载器 */
    protected loader: ResourceLoader = null!;

    /** 当前MainController所在节点 */
    protected node: Node = null!;

    /** 当胆入口是否已经运行中 */
    isRunning: boolean = false;

    constructor() {
        this.loader = new ResourceLoader();
    }

    /** init之后触发,由管理器统一调度 */
    onLoad(node: Node): void {
        this.node = node;
        this.isRunning = true;
    }

    /** 场景销毁时触发,管理器统一调度 */
    onDestroy(): void {
        this.isRunning = false;
    }

    /** 管理器通知自己进入GameView */
    onEnter(): void {
        //初始化游戏数据
        this.initData();
        //添加网络事件
        this.addNetHandler();
        //暂停当前网络处理队列，等资源加载完成后打开界面
        this.pauseMessageQueue();
        //加载资源
        this.loadResources(() => {
            this.openGameView();
        });
    }

    /** 卸载bundle,即在自己bundle删除之前最后的一条消息 */
    onUnloadBundle(): void {
        //移除本模块网络事件
        this.removeNetHandler();
        //关闭视图
        this.closeGameView();
        //卸载资源
        this.unloadResources();
    }

    /** 加载模块资源 */
    protected abstract loadResources(completeCb: () => void): void;
    protected unloadResources(): void {
        this.loader.unLoadResources();
    }

    /** 打开游戏主场景视图 */
    protected abstract openGameView(): void;
    protected abstract closeGameView(): void;

    /** 初始化游戏数据 */
    protected abstract initData(): void;

    /** 添加该模块网络事件 */
    protected addNetHandler(): void {};
    protected removeNetHandler(): void {};
    /** 暂停网络 */
    protected pauseMessageQueue(): void {};

    protected resumeMessageQueue(): void {};

    /** 外部模块可直接指定bund进行去bundle内调用 */
    public call(eventName: string, args: any[]): void {}
}
