export default class ArrayUtil {
    public static getElementIndex<T>(arr: Array<T>, element: T): number {
        return arr.findIndex((value, index, arr) => {
            return value == element;
        });
    }

    public static deleteElement<T>(arr: Array<T>, element: T): number {
        let index = this.getElementIndex(arr, element);
        if (index >= 0) {
            arr.splice(index);
        }
        return index;
    }

    public static createArray<T>(len: number, defaultValue: any) {
        let ret = new Array<T>(len);
        if (defaultValue != undefined) {
            for (let i = 0; i < ret.length; ++i) {
                ret[i] = defaultValue;
            }
        }
        return ret;
    }

    public static deleteElements<T>(
        arr: Array<T>,
        element: T,
        compareFun: (lhs: T, rhs: T) => boolean
    ): number {
        let removeList = [];
        for (let i = 0; i < arr.length; ++i) {
            if (compareFun(arr[i], element)) {
                removeList.push(i);
            }
        }

        for (let i = removeList.length - 1; i >= 0; --i) {
            arr.splice(removeList[i]);
        }
        return removeList.length;
    }
}
