

/**
 * 采用arrayBuffer
 * websocket 封装
 */

import { Global } from "../../main/Global";
import ComponentMgr from "../../mgr/ComponentMgr";


export default class NetSocket {
    private socket: WebSocket = null!;
    // private onClose: Function = null;

    public connect(isSsl: boolean, ip: string, port: number, userToken: string, onClose: Function, onMessage: Function, onOpen: Function) {
        if (this.socket) {
            return;
        }
        let wsP = isSsl ? "wss://" : "ws://";
        let portP = isSsl ? "/ws?wsport=" : ":";
        // let addr = wsP + ip + portP + port;
        // let addr = ip;
        // let addr =  `${ip}:80`;
        Log.d("socket 连接.......... ", ip);
        this.socket = new WebSocket(ip,[]);

        if (!this.socket) {
            console.error("socket 连接错误 ", ip);
            return;
        }

        this.socket.onopen = (event) => {
            onOpen && onOpen();
        };

        this.socket.onmessage = (event) => {
            let data: ArrayBuffer = event.data;
            let dataSize = data.byteLength;
            if (dataSize <= 0) {
                console.warn("dataSize <= 0");
                return;
            }
            onMessage && onMessage(data);
        };

        this.socket.onclose = (event) => {
            Log.d("websocekt close++++++++++++++", event.code, event.reason);
            this.socket = null!;
            onClose && onClose();
        };
        this.socket.onerror = (event) => {
            console.warn("websocket 错误++++++++++++++++");
        };
        this.socket.binaryType = "arraybuffer";
    }

    public send(data: string): void {
        if (!this.socket) {
            // console.warn("websocket 已断开,正在执行重连");
            // Global.gameCtrl.doReconnect();
            return;
        }
        if (this.socket.readyState != 1) {
            console.warn("websocket 还不完成连接");
            return;
        }
        this.socket.send(data);
    }

    public disconnect(): void {
        if (!this.socket) {
            return;
        }
        this.socket.close();
        this.socket = null!;
    }

    public getCurState(): number {
        if (!this.socket) {
            return -1;
        }
        return this.socket.readyState;
    }
}
