@ccclass('Img')
export class Img extends Component {

    start() {
        // [3]
    }


    initImg(url: string, cb?:Function) {
        this.getComponent(Sprite)!.spriteFrame = null;
        ResManager.Instance().loadRemoteImg(url, true, (spriteFrame: SpriteFrame) => {
            if(this.node){
                this.getComponent(Sprite)!.spriteFrame = spriteFrame;
                if(cb){
                    cb();
                }
            }
            
        })
     
    }
    initWithSpriteFrame(spriteFrame:SpriteFrame){
        this.getComponent(Sprite)!.spriteFrame = spriteFrame;
    }
 
}

