import { sys, url, loader, error } from "cc";
import { SocketBase, SocketEvent, SocketState } from "./SocketBase";

/**
 * WebSocket
 */
export default class WebSock extends SocketBase {
	private _webSocket: WebSocket;

	connect() {
		if (this._webSocket && this._webSocket.readyState != WebSocket.CLOSED) return;
		if (sys.isNative && sys.os == sys.OS.ANDROID) {
			// let cacert = 'resources/cacert.pem';
			this._webSocket = new WebSocket(this._url);
		} else {
			//其他平台直接使用
			this._webSocket = new WebSocket(this._url);
		}
		let ws = this._webSocket;
		ws.binaryType = "arraybuffer";
		ws.onopen = (event) => {
			this.dispatch(SocketEvent.Open, event);
		};
		ws.onmessage = (event) => {
			this._onMessage(event.data);
		};
		ws.onerror = (event) => {
			this.dispatch(SocketEvent.Error);
		};
		ws.onclose = (event) => {
			this.dispatch(SocketEvent.Close, event.reason);
		};
	}

	private _onMessage(message: { data: string | ArrayBuffer }): void {
		this.dispatch(SocketEvent.Message, message);
	}

	/**
	 * 发送数据
	 * @param data {string | ArrayBuffer}
	 */
	send(data: string | ArrayBuffer) {
		this._webSocket.send(data);
	}

	close() {
		if (!this._webSocket) {
			return;
		}
		try {
			if (this._webSocket.readyState != WebSocket.CLOSED) this._webSocket.close();
		} catch (err) {
			error("error while closing webSocket ", err.toString());
		}
		this._webSocket = null;
	}

	getState() {
		if (this._webSocket) {
			switch (this._webSocket.readyState) {
				case WebSocket.OPEN:
					return SocketState.OPEN;
				case WebSocket.CONNECTING:
					return SocketState.CONNECTING;
				case WebSocket.CLOSING:
					return SocketState.CLOSING;
				case WebSocket.CLOSED:
					return SocketState.CLOSED;
			}
		}
		return SocketState.CLOSED;
	}
}
