import { Mask, UITransform, _decorator } from "cc";
const { ccclass, property, executeInEditMode } = _decorator;

@ccclass("PMask")
@executeInEditMode
export class PMask extends Mask {
    private _round: number = 15;

    get round() {
        return this._round;
    }
    @property({
        displayName: "设置圆角",
        visible: function () {
            return this.type === Mask.Type.GRAPHICS_STENCIL;
        },
    })
    set round(value: number) {
        if (this._round === value) {
            return;
        }
        this._round = value;

        this.updateMask();
    }

    private _xDiff: number = 0;//x偏移
    get xDiff() {
        return this._xDiff;
    }
    @property({
        displayName: "xDiff",
        visible: function () {
            return this.type === Mask.Type.GRAPHICS_STENCIL;
        },
    })
    set xDiff(value: number) {
        if (this._xDiff === value) {
            return;
        }
        this._xDiff = value;

        this.updateMask();
    }
    private _yDiff: number = 0;//y偏移
    get yDiff() {
        return this._yDiff;
    }
    @property({
        displayName: "yDiff",
        visible: function () {
            return this.type === Mask.Type.GRAPHICS_STENCIL;
        },
    })
    set yDiff(value: number) {
        if (this._yDiff === value) {
            return;
        }
        this._yDiff = value;

        this.updateMask();
    }
    private _widthDiff: number = 0;//width偏移
    get widthDiff() {
        return this._widthDiff;
    }
    @property({
        displayName: "widthDiff",
        visible: function () {
            return this.type === Mask.Type.GRAPHICS_STENCIL;
        },
    })
    set widthDiff(value: number) {
        if (this._widthDiff === value) {
            return;
        }
        this._widthDiff = value;

        this.updateMask();
    }
    private _heightDiff: number = 0;//height偏移
    get heightDiff() {
        return this._heightDiff;
    }
    @property({
        displayName: "heightDiff",
        visible: function () {
            return this.type === Mask.Type.GRAPHICS_STENCIL;
        },
    })
    set heightDiff(value: number) {
        if (this._heightDiff === value) {
            return;
        }
        this._heightDiff = value;

        this.updateMask();
    }


    start() {
        this.updateMask();
    }

    updateMask() {
        if (this.type == Mask.Type.GRAPHICS_STENCIL) {
            this._graphics.clear();
            this._graphics.roundRect(
                -this.node.getComponent(UITransform)!.width / 2+this._xDiff,
                -this.node.getComponent(UITransform)!.height / 2+this._yDiff,
                this.node.getComponent(UITransform)!.width+this._widthDiff,
                this.node.getComponent(UITransform)!.height+this._heightDiff,
                this.round
            );
            this._graphics.roundRect
            this._graphics.fill();
        }
    }
}
