import {
    _decorator,
    Asset,
    director,
    instantiate,
    Node,
    Prefab,
    Component,
} from "cc";
import { UILayer } from "../framework/ui/UILayer";
import { UIManager } from "../framework/ui/UIManager";
import { Global } from "../main/Global";
import { GameManager } from "../mgr/GameManager";

const { ccclass, property } = _decorator;

// cc.macro.CLEANUP_IMAGE_CACHE=false
// dynamicAtlasManager.enabled = true;

@ccclass("LoadingScene")
export class LoadingScene extends Component {
    @property({ displayName: "psersistantNode", type: Node })
    public psersistantNode: Node = null!;
    @property(Prefab)
    uiLayer: Prefab = null;
    @property({ displayName: "wssCacert", type: Asset })
    public wssCacert: Asset = null!;

    onLoad() {
        this.addUILayer();
        Global.loadingScene = this;
        director.addPersistRootNode(this.psersistantNode);
        Global.psersistantNode = this.psersistantNode;
    }

    addUILayer() {
        let uiLayer = UIManager.getInstance().uiLayer as UILayer;
        if (!uiLayer) {
            let node = instantiate(this.uiLayer);
            director.addPersistRootNode(node);
        }
    }

    start() {
        Global.wssCacert = this.wssCacert;
    }
}
