import { UIView, UIZIndex } from "../ui/UIView";
import { Singleton } from "../Singleton";
import { Eventer } from "../Eventer";
import { Events } from "../Events";
import { UIMask } from "../ui/UIMask";
import {
    Node,
    BlockInputEvents,
    Component,
    director,
    find,
    instantiate,
    isValid,
    Prefab,
    resources,
    Tween,
    tween,
    warn,
    UITransform,
    view,
    UIOpacity,
    v3,
    Sprite,
    color,
} from "cc";
import { ResManager } from "../manager/ResManager";
import UIAdapter from "./UIAdapter";
import LogUtil from "../../common/utils/LogUtil";

/** UI结构体 */
export interface UIInfo {
    uiId: number;
    uiView: UIView;
    uiArgs: any;
    preventNode?: Node;
    zOrder?: number;
    isClose?: boolean;
}

/** UI配置结构体 */
export interface UIConf {
    bundle?: string;
    prefab: string;
    isPreload?: boolean;
}

/**
 * UILayer接口定义，需要按照项目需求在framework外实现
 */
export interface IUILayer extends Component {
    addView(view: UIView): void;
}

/**预加载标志 */
export const UI_PRELOAD_STR = 'preload';

/**
 * 界面管理类
 */
export class UIManager extends Singleton<UIManager>() {
    /** 背景UI数量（有若干层UI是作为背景UI，而不受切换等影响）*/
    private bgCount = 0;
    /** 是否正在关闭UI */
    private isClosing = false;
    /** 是否正在打开UI */
    isOpening = false;
    /** UI界面缓存（key为UIId，value为UIView节点）*/
    private uiCache: { [UIId: number]: UIView } = {};
    /** UI界面栈（{UIID + UIView + UIArgs}数组）*/
    private uiStack: UIInfo[] = [];
    /** UI待打开列表 */
    private uiOpenQueue: UIInfo[] = [];
    /** UI待关闭列表 */
    private uiCloseQueue: number[] = [];
    /** UI配置 */
    private uiConf: { [key: number]: UIConf } = {};
    /**打开和关闭动画的回调 */
    private aniCallback: Function = null;
    uiLayer: IUILayer = null;
    /** UI最高层 */
    private uiTop: number;

    /**
     * 初始化所有UI的配置对象
     * @param conf 配置对象
     */
    init(conf: { [key: number]: UIConf }): void {
        this.uiConf = conf;
        UIAdapter.initResolution();
    }

    /**
     * 设置或覆盖某uiId的配置
     * @param uiId 要设置的界面id
     * @param conf 要设置的配置
     */
    setUIConf(conf: { [key: number]: UIConf }): void {
        if (conf) {
            for (let k in conf) {
                this.uiConf[k] = conf[k];
            }
        }
    }

    /**
     * 添加防触摸层
     */
    addPreventTouch(parent?: Node) {
        let node = new Node();
        node.name = "preventTouch";
        node.addComponent(UITransform).setContentSize(view.getVisibleSize());
        node.addComponent(BlockInputEvents);
        node.parent = parent ?? this.uiLayer.node;
        return node;
    }

    /**
     * 移除屏蔽层
     */
    removePreventTouch(parent?: Node) {
        parent = parent ?? this.uiLayer.node;
        let child = parent.getChildByName("preventTouch");
        if (child) child.destroy();
    }

    /** 自动执行下一个待关闭或待打开的界面 */
    private autoExecNextUI() {
        // 逻辑上是先关后开
        if (this.uiCloseQueue.length > 0) {
            let uiId = this.uiCloseQueue[0];
            this.uiCloseQueue.splice(0, 1);
            this.closeToUI(uiId);
        }
        if (this.uiOpenQueue.length > 0) {
            let uiQueueInfo = this.uiOpenQueue[0];
            this.uiOpenQueue.splice(0, 1);
            this.open(uiQueueInfo.uiId, uiQueueInfo.uiArgs);
        }
    }

    /**
     * 自动检测动画组件以及特定动画，如存在则播放动画，无论动画是否播放，都执行回调
     * @param bShow
     * @param aniOverCallback 动画播放完成回调
     */
    private autoExecAnimation(
        uiView: UIView,
        bShow: boolean,
        aniOverCallback: () => void
    ) {
        let func = () => {
            this.removePreventTouch(uiView.node);
            aniOverCallback();
        };
        if (uiView.bAni && uiView.background) {
            Tween.stopAllByTarget(uiView.node);
            if (this.aniCallback) {
                this.aniCallback();
            }
            if (bShow) {
                this.showView(uiView, func);
            } else if (uiView.bAni) {
                this.addPreventTouch(uiView.node);
                this.hideView(uiView, func);
            } else {
                aniOverCallback();
            }
        } else {
            aniOverCallback();
        }
    }

    /**
     * 自动检测资源预加载组件，如果存在则加载完成后调用completeCallback，否则直接调用
     * @param completeCallback 资源加载完成回调
     */
    private autoLoadRes(uiView: UIView, completeCallback: () => void) {
        // 暂时先省略
        completeCallback();
    }

    /**
     * 异步加载一个UI的prefab，成功加载了一个prefab之后
     * @param uiId 界面id
     * @param completeCallback 加载完成回调
     * @param uiArgs 初始化参数
     */
    private getOrCreateUI(
        uiId: number,
        completeCallback: (uiView: UIView) => void,
        uiArgs: any
    ): void {
        // 如果找到缓存对象，则直接返回
        let uiView: UIView = this.uiCache[uiId];
        if (uiView) {
            LogUtil.debug(`getOrCreateUI ${uiId} completeCallback!`);
            completeCallback(uiView);
            return;
        }

        // 找到UI配置
        let uiPath = this.uiConf[uiId].prefab;
        if (null == uiPath) {
            warn(`getOrCreateUI ${uiId} fail, prefab conf not found!`);
            completeCallback(null);
            return;
        }

        let createNode = (prefab: Prefab) => {
            // 检查实例化错误
            let uiNode: Node = instantiate(prefab);
            if (null == uiNode) {
                warn(`getOrCreateUI instantiate ${uiId} fail, path: ${uiPath}`);
                completeCallback(null);
                return;
            }
            // 检查组件获取错误
            uiView = uiNode.getComponent(UIView);
            if (null == uiView) {
                warn(
                    `getOrCreateUI getComponent ${uiId} fail, path: ${uiPath}`
                );
                uiNode.destroy();
                completeCallback(null);
                return;
            }
            // 异步加载UI预加载的资源
            this.autoLoadRes(uiView, () => {
                uiView.init(uiArgs);
                completeCallback(uiView);
            });
        };

        let bundle = this.uiConf[uiId].bundle;
        if (bundle) {
            ResManager.Instance().load(bundle, uiPath, Prefab, null, (data) => {
                if (data && data.data && data.data instanceof Prefab) {
                    createNode(data.data);
                }
                else {
                    warn(`load prefab : ${uiPath} fail`);
                    completeCallback(null);
                    return;
                }
            });
        } else {
            resources.load(uiPath, (err: Error, prefab: Prefab) => {
                // 检查加载资源错误
                if (err) {
                    warn(
                        `CreateUI loadRes ${uiId} fail, path: ${uiPath} error: ${err}`
                    );
                    completeCallback(null);
                    return;
                }
                if (uiArgs == UI_PRELOAD_STR) {
                    this.isOpening = false;
                    this.autoExecNextUI();
                } else {
                    createNode(prefab);
                }
            });
        }
    }

    /**
     * UI被打开时回调，对UI进行初始化设置，刷新其他界面的显示，并根据
     * @param uiId 哪个界面被打开了
     * @param uiView 界面对象
     * @param uiInfo 界面栈对应的信息结构
     * @param uiArgs 界面初始化参数
     */
    private onUIOpen(
        uiId: number,
        uiView: UIView,
        uiInfo: UIInfo,
        uiArgs: any
    ) {
        if (null == uiView) {
            return;
        }
        // 激活界面
        uiInfo.uiView = uiView;
        uiView.node.active = true;
        uiView.uiId = uiId;
        // 添加到场景中
        let parent = director.getScene().getChildByName("Canvas");
        if (isValid(this.uiLayer)) parent = this.uiLayer.node;
        uiView.node.parent = parent;
        this.setSiblingIndex(uiView.node, (uiInfo.zOrder || this.uiStack.length));

        // 刷新其他UI
        // this.updateUI();

        // 打开界面之前回调
        Eventer.getInstance().emit(Events.UIOpenBefore, uiId);

        // 执行onOpen回调
        uiView.onOpen(uiArgs);
        this.addUIViewFunc(uiView);
        this.autoExecAnimation(uiView, true, () => {
            this.aniCallback = null;
            if (isValid(uiView.node)) {
                uiView.onOpenAniOver();
                Eventer.getInstance().emit(Events.UIOpen, uiId);
            } else {
                this.removeMask();
            }
        });
    }

    /**
     * 添加快速关闭及遮罩
     * @param uiView
     */
    private addUIViewFunc(uiView: UIView) {
        let background = find("background", uiView.node);
        if (background && !uiView.background) {
            uiView.background = background;
        }
        // 快速关闭界面的设置，绑定界面中的background，实现快速关闭
        if (uiView.quickClose) {
            if (uiView.background) {
                uiView.background.addComponent(BlockInputEvents);
            }
        }
        // 遮罩
        this.addMask(uiView);
    }

    /** 打开界面并添加到界面栈中 */
    async open(uiId: number, uiArgs: any = null): Promise<UIView> {
        console.log(`open uiId: ${uiId}`);
        let uiInfo: UIInfo = {
            uiId: uiId,
            uiArgs: uiArgs,
            uiView: null,
        };
        if (this.isOpening || this.isClosing) {
            // 插入待打开队列
            this.pushUI(uiInfo);
            return;
        }

        // 重复打开了同一个界面，返回
        let uiIndex = this.getUIIndex(uiId);
        console.log(`open uiId getUIIndex: ${uiIndex}`);
        if (-1 != uiIndex) {
            let info = this.uiStack[uiIndex];
            if (info && info.uiView && isValid(info.uiView.node)) {
                info.uiView.node.parent = this.uiLayer.node;
                info.uiView.node.active = true;
            }
            return;
        }

        // 设置UI的zOrder
        let topUI = this.getTopUI();
        if (topUI && topUI.node.active) {
            uiInfo.zOrder = topUI.node.getSiblingIndex() + 1;
        } else {
            uiInfo.zOrder = this.uiStack.length + 1;
        }

        this.isOpening = true;
        // 预加载资源，并在资源加载完成后自动打开界面
        return new Promise((res, rej) => {
            this.getOrCreateUI(
                uiId,
                (uiView: UIView): void => {
                    // 如果界面已经被关闭或创建失败
                    if (uiInfo.isClose || null == uiView) {
                        warn(
                            `getOrCreateUI ${uiId} fail! close state : ${uiInfo.isClose} , uiView : ${uiView}`
                        );
                        this.isOpening = false;
                        if (uiInfo.preventNode) {
                            uiInfo.preventNode.destroy();
                            uiInfo.preventNode = null;
                        }
                        return;
                    }
                    // if(this.uiCloseQueue.indexOf(uiId) > -1) {
                    //     this.isOpening = false;
                    //     this.uiCloseQueue.splice(this.uiCloseQueue.indexOf(uiId), 1);
                    //     return;
                    // }
                    this.uiStack.push(uiInfo);
                    // 打开UI，执行配置
                    this.onUIOpen(uiId, uiView, uiInfo, uiArgs);
                    this.isOpening = false;
                    this.autoExecNextUI();
                    if (isValid(uiView)) {
                        res(uiView);
                    } else {
                        rej();
                    }
                },
                uiArgs
            );
        });
    }

    /** 替换栈顶界面 */
    replace(uiId: number, uiArgs: any = null) {
        this.close(this.uiStack[this.uiStack.length - 1].uiView);
        this.open(uiId, uiArgs);
    }

    private addMask(uiView: UIView) {
        if (!uiView || !uiView.isMask || !uiView.node || !isValid(this.uiLayer)) return;
        let maskNode = find("UIMask", this.uiLayer.node);
        let mask = maskNode && maskNode.getComponent(UIMask);
        if (mask) {
            mask.addMask(uiView);
        }
    }

    removeMask() {
        if (!isValid(this.uiLayer)) return;
        let maskNode = find("UIMask", this.uiLayer.node);
        let mask = maskNode && maskNode.getComponent(UIMask);
        if (mask) {
            mask.removeMask();
        }
    }

    /**
     * 关闭当前界面
     * @param closeUI 要关闭的界面
     */
    close(closeUI?: UIView) {
        // if (this.uiStack.length < 1 || this.isClosing || this.isOpening) {
        //     if (closeUI) {
        //         // 插入待关闭队列
        //         this.uiCloseQueue.push(closeUI.uiId);
        //     }
        //     return;
        // }

        let uiInfo: UIInfo;
        if (closeUI) {
            for (let index = this.uiStack.length - 1; index >= 0; index--) {
                let ui = this.uiStack[index];
                if (ui.uiView === closeUI) {
                    uiInfo = ui;
                    this.uiStack.splice(index, 1);
                    break;
                }
            }
            // 找不到这个UI
            if (uiInfo === undefined) {
                return;
            }
        } else {
            uiInfo = this.uiStack.pop();
        }

        // 关闭当前界面
        let uiId = uiInfo.uiId;
        let uiView = uiInfo.uiView;
        uiInfo.isClose = true;
        this.isClosing = true;

        if (null == uiView) {
            return;
        }
        // 执行关闭动画
        this.autoExecAnimation(uiView, false, () => {
            this.isClosing = false;
            this.aniCallback = null;
            uiView.onClose();
            this.removeMask();
            Eventer.getInstance().emit(Events.UIClose, uiId);
            if (isValid(uiView.node)) {
                if (uiView.cache) {
                    this.uiCache[uiId] = uiView;
                    uiView.node.removeFromParent();
                } else {
                    uiView.node.destroy();
                }
            }
            this.autoExecNextUI();
        });
    }

    /**
     * 关闭所有界面
     * @param exceptIds 除了这些不关闭
     */
    closeAll(exceptIds?: number[]) {
        let checkEx = (uiid: number) => {
            if (!exceptIds) return false;
            for (let id of exceptIds) {
                if (uiid == id) {
                    return true;
                }
            }
            return false;
        };
        for (var i: number = 0; i < this.uiStack.length; i++) {
            let uiInfo = this.uiStack[i];
            if (!checkEx(uiInfo.uiId)) {
                uiInfo.uiView.close();
                i--;
            }
        }
        // this.uiStack = [];
        this.uiOpenQueue = [];
        this.uiCloseQueue = [];
        this.isOpening = false;
        this.isClosing = false;
    }

    /**
     * 关闭界面，
     * @param uiId 要关闭到的uiId（关闭其顶部的ui）
     */
    closeToUI(uiId: number): void {
        let idx = this.getUIIndex(uiId);
        console.log(`closeToUI uiId getUIIndex: ${uiId}`);
        if (-1 == idx) return;
        // if (this.isClosing || this.isOpening) {
        //     if (uiId >= 0) {
        //         // 插入待关闭队列
        //         if(this.uiCloseQueue.indexOf(uiId) < 0) {
        //             this.uiCloseQueue.push(uiId);
        //         }
        //     }
        //     return;
        // }
        let uiInfo = this.uiStack[idx];
        if (uiInfo) this.close(uiInfo.uiView);
    }

    /** 清理界面缓存 */
    clearCache(): void {
        for (const key in this.uiCache) {
            let ui = this.uiCache[key];
            if (isValid(ui.node)) {
                ui.node.destroy();
            }
        }
        this.uiCache = {};
    }

    /******************** UI的便捷接口 *******************/
    isTopUI(uiId): boolean {
        if (this.uiStack.length == 0) {
            return false;
        }
        return this.uiStack[this.uiStack.length - 1].uiId == uiId;
    }

    getUI(uiId: number): UIView {
        for (let index = 0; index < this.uiStack.length; index++) {
            let v = this.uiStack[index];
            if (uiId == v.uiId) {
                return v.uiView;
            }
        }
        return null;
    }

    getTopUI(): UIView {
        for (let i = this.uiStack.length - 1; i >= 0; i--) {
            let uiInfo = this.uiStack[i];
            if (uiInfo.uiView.node.getSiblingIndex() < UIZIndex.notice) {
                return uiInfo.uiView;
            }
        }
        return null;
    }

    getUIIndex(uiId: number): number {
        for (let index = 0; index < this.uiStack.length; index++) {
            const element = this.uiStack[index];
            if (uiId == element.uiId) {
                if (isValid(element.uiView.node)) {
                    return index;
                } else {
                    this.uiStack.splice(index, 1);
                    return -1;
                }
            }
        }
        return -1;
    }

    /**
     * 检查是否还有遮罩界面 (exView除外)
     * @returns
     */
    checkMaskView(exView?) {
        for (let i = this.uiStack.length - 1; i >= 0; i--) {
            let uiInfo = this.uiStack[i];
            if (
                uiInfo &&
                uiInfo.uiView &&
                isValid(uiInfo.uiView.node) &&
                uiInfo.uiView.node.active &&
                uiInfo.uiView.isMask &&
                uiInfo.uiView != exView
            ) {
                return uiInfo.uiView;
            }
        }
        return null;
    }

    /** 显示视图动画 */
    private showView(uiView: UIView | null, completeCallback: Function) {
        let normalAni = () => {
            if (uiView.node) {
                this.playCommonPopUpAni(uiView.node, () => {
                    if (completeCallback) {
                        completeCallback();
                    }
                });
            }
        };
        normalAni();
        this.aniCallback = completeCallback;
    }

    /** 隐藏/关闭视图统一动画 */
    private hideView(uiView: UIView | null, completeCallback: Function) {
        if (uiView && uiView.node) {
            this.playCommonPopBackAni(uiView.node, () => {
                if (completeCallback) {
                    completeCallback();
                }
            });
            this.aniCallback = completeCallback;
        }
    }

    /** 尝试给打开or关闭的UIView的遮罩播放渐显or渐隐 */
    tryPlayUIMaskFadeInOrOut(newView?: UIView, time?, close?) {
        if (!newView || !newView.isMask) return;

        if (!isValid(this.uiLayer)) return;
        let uiMaskNode = find("UIMask", this.uiLayer.node);
        if (!uiMaskNode || !uiMaskNode.active) return;

        let isHasOtherMaskUI = !!this.checkMaskView(newView);
        if (isHasOtherMaskUI) {
            if (close) this.removeMask(); // 关闭情况下，先把mask移下去再缩放
            return;
        }

        let op = uiMaskNode.getComponent(UIOpacity);
        if (!op) op = uiMaskNode.addComponent(UIOpacity);
        Tween.stopAllByTarget(op);
        if (!close) {
            op.opacity = 0;
            tween(op)
                .to(time, { opacity: 255 })
                .start();
        } else {
            tween(op)
                .to(time, { opacity: 0 })
                .start();
        }
    }

    /**
     * 通用弹窗弹出动画
     * @param node
     * @param cb
     */
    playCommonPopUpAni(node: Node, cb: Function = null!) {
        let time = 0.2;
        tween(node).stop();
        node.scale = v3(0.2, 0.2, 0.2);
        tween(node)
            .to(time, { scale: v3(1, 1, 1) }, { easing: 'expoOut' })
            .call(() => {
                if (cb) cb();
            })
            .start();

        let op = node.getComponent(UIOpacity);
        if (!op) op = node.addComponent(UIOpacity);
        op.opacity = 0;
        Tween.stopAllByTarget(op);
        tween(op)
            .to(time, { opacity: 255 })
            .start();

        this.tryPlayUIMaskFadeInOrOut(node.getComponent(UIView), time);
    }

    /**
     * 通用弹窗收回动画
     * @param node
     * @param cb
     */
    playCommonPopBackAni(node: Node, cb: Function = null!) {
        let time = 0.1;
        tween(node).stop();
        tween(node)
            .to(time, { scale: v3(0.5, 0.5, 0.5) }, { easing: 'smooth' })
            .call(() => {
                if (cb) cb();
            })
            .start();

        let op = node.getComponent(UIOpacity);
        if (!op) op = node.addComponent(UIOpacity);
        Tween.stopAllByTarget(op);
        tween(op)
            .to(time, { opacity: 0 })
            .start();

        this.tryPlayUIMaskFadeInOrOut(node.getComponent(UIView), time, true);
    }

    private refreshzOrder() {
        let list = this.uiStack.filter((element) => element.uiId == this.uiTop);
        if (list.length <= 0)
            return;
        let uiInfo = list[0];
        let node = uiInfo?.uiView?.node;
        if (!node || !node.parent)
            return;
        node.setSiblingIndex(node.parent.children.length);
    }

    setSiblingIndex(node: Node, zIndex: number) {
        node.setSiblingIndex(zIndex);
        // this.uiLayer.scheduleOnce(() => {
        this.refreshzOrder();
        this.updateZIndex(this.uiLayer.node);
        // });
    }

    /** 根据zIndex统一设置节点顺序(同一父节点，一帧最多只需调用一次) */
    updateZIndex(parent: Node): void {
        let children = parent.children.concat();
        children.sort((a, b): number => {
            if (a.zIndex == null) {
                a.zIndex = 0;
            }
            if (b.zIndex == null) {
                b.zIndex = 0;
            }
            return a.zIndex - b.zIndex;
        });
        let maxIndex = children.length;
        for (const node of children) {
            node.setSiblingIndex(maxIndex);
        }
    }

    /**
     * 插入ui队列
     * @param uiInfo 
     */
    private pushUI(uiInfo: UIInfo) {
        if (this.uiOpenQueue.length > 0 && (!uiInfo.uiArgs || uiInfo.uiArgs != UI_PRELOAD_STR)) {
            let i = 0
            for (let info of this.uiOpenQueue) {
                if (info.uiArgs && info.uiArgs == UI_PRELOAD_STR) {
                    Log.d(`==pushUI==${uiInfo.uiId}===`)
                    this.uiOpenQueue.splice(i, 0, uiInfo);
                    break;
                }
                i++;
            }
        } else {
            this.uiOpenQueue.push(uiInfo);
        }
    }
}
