import { assetManager, sys } from 'cc';
import { Global } from '../../../main/Global';
import { HttpMethod } from '../../define/EnumDefine';
import { HttpResponseType } from '../../define/StructDefine';
import { ProtoUtil } from '../../utils/ProtoUtil';
import { HttpReqPack } from './HttpReqPack';
import { HttpRespPack } from './HttpRespPack';
import NetHttp, { HTTP_CONTENT_TYPE } from './NetHttp';
import WebMsgHandler from './WebMsgHandler';

export class HttpMgr {
    private static _instance: HttpMgr = null!;
    public static Instance() { return this._instance || (this._instance = new HttpMgr()); }
    public send(httpReqMsg: HttpReqPack,
        userdata?: any,
        resp?: (msg: HttpRespPack, userdata: any) => void,
        thisArg?: any,
        contentType: HTTP_CONTENT_TYPE = HTTP_CONTENT_TYPE.JSON
    ) {
        // if(!NetAdaptor.bAdaptor) {
        let httpUrl = Global.httpSvr + httpReqMsg.key;
        let data = null;
        if (typeof httpReqMsg.data !== "string") {
            data = ProtoUtil.getHttpParam(httpReqMsg.data);
            data = httpReqMsg.respFormat == HttpResponseType.TEXT ? ProtoUtil.parseToString(data) : data;
        } else {
            data = httpReqMsg.data;
        }

        if (httpReqMsg.method == HttpMethod.POST) {
            WebMsgHandler.sendPost(httpUrl, null, data, resp, resp, null, false, contentType);
        } else if (httpReqMsg.method == HttpMethod.GET) {
            WebMsgHandler.sendGet(httpUrl + data, null, resp, resp, null, contentType);
        }
        // } else {
        //     HttpManager.getInstance().request(
        //         new HttpRequest<{}, HttpRespPack, HttpMgr>(
        //             this,
        //             httpReqMsg.key,
        //             httpReqMsg.data,
        //             (data: HttpRespPack) => {
        //                 if(resp) resp(data, null)
        //             }
        //         )
        //     );
        // }
    }

    /**
     * 游戏短链接
     * @param httpReqMsg 
     * @param userdata 
     * @param resp 
     * @param thisArg 
     */
    public sendGameShort(
        httpReqMsg: HttpReqPack,
        contentType: HTTP_CONTENT_TYPE = HTTP_CONTENT_TYPE.URLENCODED,
        resp?: (msg: HttpRespPack, userdata: any) => void,
    ) {
        let httpUrl = Global.gameShortSvr + httpReqMsg.key;
        let data = null;
        if (typeof httpReqMsg.data !== "string") {
            data = ProtoUtil.getHttpParam(httpReqMsg.data);
            data = httpReqMsg.respFormat == HttpResponseType.TEXT ? ProtoUtil.parseToString(data) : data;
        } else {
            data = httpReqMsg.data;
        }

        if (httpReqMsg.method == HttpMethod.POST) {
            WebMsgHandler.sendPost(httpUrl, null, data, resp, resp, null, false, contentType);
        } else if (httpReqMsg.method == HttpMethod.GET) {
            WebMsgHandler.sendGet(httpUrl + data, null, resp, resp, null, contentType);
        }
    }

    loadRemoteJson(url: string, params?: any, onComplete?: (err: Error | null, data: any) => void) {
        if (sys.os == sys.OS.IOS) {
            let http = new NetHttp();
            http.init(null);
            http.sendGet(url, null, (msg: HttpRespPack, userdata: any) => {
                onComplete(null, { json: msg.data });
            }, (msg: HttpRespPack, userdata: any) => {
                onComplete({ name: url, message: "error" }, null);
            })
        } else {
            if (params) {
                assetManager.loadRemote(url, params, onComplete);
            } else {
                assetManager.loadRemote(url, onComplete);
            }
        }
    }

}

