import { director, JsonAsset } from "cc";
import { LanguageLabel } from "./LanguageLabel";
import { LanguageSprite } from "./LanguageSprite";
import { Macro } from "../../common/define/HotUpdateDefine";
import { Global } from "../../main/Global";
import { Singleton } from "../Singleton";
import { ResManager } from "../manager/ResManager";
import { ResDefine } from "../../common/define/ResDefine";
import { Resource } from "../hall/Resource";

export default class i18n extends Singleton<i18n>() {

    bundleName = Macro.BUNDLE_RESOURCES;

    /** i18n Main 配表 */
    static i18nMainConfig = {}

    /**
     * 构造函数
     */
    static init() {
        return new Promise((resolve, reject) => {
            ResManager.Instance().load(
                Macro.BUNDLE_RESOURCES,
                ResDefine.CONFIG_LOCATION,
                JsonAsset,
                () => { },
                (res: Resource.CacheData) => {
                    let data: any = res.data!;
                    this.i18nMainConfig = data.json['i18n_main'];
                    resolve(null);
                }
            );
        });
    }

    /**
     * 刷新语言文字
     * @param lang
     */
    static updateLanguage() {
        let rootNodes = director.getScene()!.children;
        for (let i = 0; i < rootNodes.length; ++i) {
            // 更新所有的LanguageLabel节点
            let languagelabels =
                rootNodes[i].getComponentsInChildren(LanguageLabel);
            for (let j = 0; j < languagelabels.length; j++) {
                languagelabels[j].language();
            }
            // 更新所有的LanguageSprite节点
            let languagesprites =
                rootNodes[i].getComponentsInChildren(LanguageSprite);
            for (let j = 0; j < languagesprites.length; j++) {
                languagesprites[j].language();
            }
        }
    }

    /**
     * 替换文本中的变量(变量索引不要超过10)
     */
    static formatString(
        str: string,
        parms: Array<any> = [],
        replaceValue: string = "%"
    ): string {
        if (!str) {
            return "";
        }

        let result = str.replace("\\n", "\n");
        if (parms && parms.length > 0) {
            let replaceCnt: number = 1;
            for (let i: number = 0; i < parms.length; i++) {
                let replaceStr: RegExp = new RegExp(
                    replaceValue + replaceCnt,
                    "g"
                );
                let tempStr: string = parms[i];
                result = result.replace(replaceStr, tempStr);
                replaceCnt++;
            }
        }
        return result;
    }

    private static getString(id: number): string {
        let lang = Global.language;
        let obj = i18n.i18nMainConfig[id];
        if (!obj || !obj[lang])
            return '';
        return obj[lang];
    }

    /**
     * i18n多语言
     * @param code 
     * @param args 
     * @returns 
     */
    public static tr(code: number, ...args) {
        let text = this.getString(code);
        if (!text) {
            return "{" + code + "}";
        }

        let length = args.length;
        for (let i = 0; i < length; i++) {
            text = text.replace("{" + i + "}", args[i]);
        }
        return text;
    }

    public static getSource(str: string): string {
        return str.replace("_en_", `_${Global.language}_`);
    }

    public static formatSource(img: any): string {
        return img.source.toString().replace("_en_", `_${Global.language}_`);
    }

    public static langName(lang: string): string {
        switch (lang) {
            case 'en': return
        }
    }
}
