import { _decorator, assetManager, Component, ImageAsset, JsonAsset, resources, sp, Texture2D } from 'cc';
import { Global } from '../../main/Global';
import { LOGO_PLAY_TYPE } from '../../main/GameConst';
import { Eventer } from '../../framework/Eventer';
import { Events } from '../../framework/Events';
import { ScreenType } from '../../framework/ui/UIView';
import { ResManager } from '../../framework/manager/ResManager';
import { GameUtils } from '../utils/GameUtil';
const { ccclass, property } = _decorator;



@ccclass('LogoComp')
export class LogoComp extends Component {

    @property(sp.Skeleton)
    node_logo: sp.Skeleton = null;

    private _logoSkeUrl: string = "";
    private _logoAtlasUrl: string = "";
    private _logoResUrl: string[] = [];

    /** logo纹理名字列表 */
    private _logoTexNameList: string[] = [];
    /** logo纹理列表 */
    private _logoTexList: Texture2D[] = [];
    /** logo纹理信息列表 */
    private _logoAssetsList = [];

    private _callback: Function = null;

    start() {
        this.addToStage();
        this.node_logo.node.active = false;
    }

    protected addToStage() {
        Eventer.getInstance().on(Events.ScreenSwitchEvent, this.changeScreen, this);
    }

    play(callback: Function) {
        this._callback = callback;
        this.resolvePath();

        switch (Global.logoType) {
            default:
            case LOGO_PLAY_TYPE.NONE:
                this.playEnd();
                break;
            case LOGO_PLAY_TYPE.CUSTOM:
                this.node.active = true;
                this.loadCustom();
                break;
            case LOGO_PLAY_TYPE.DEFAULT:
                this.node.active = true;
                this.playDefault();
                break;
        }
    }

    private resolvePath() {
        if (Global.logoType == LOGO_PLAY_TYPE.CUSTOM) {
            for (let str of Global.logoUrls) {
                let type = this.getFileType(str);
                switch (type) {
                    case 'png':
                        let fileName = this.getFileName(str);
                        //活动Logo
                        if (fileName == 'activity') {
                            Global.activityLogoUrl = str;
                        } else {
                            this._logoResUrl.push(str);
                        }
                        break;
                    case 'atlas': this._logoAtlasUrl = str; break;
                    case 'json': this._logoSkeUrl = str; break;
                }
            }
        }
    }

    /** 播放默认 */
    private playDefault() {

        this.node_logo.clearTrack(0);
        this.node_logo.node.active = true;
        this.node_logo.setToSetupPose();
        this.node_logo.timeScale = 1
        this.node_logo.setCompleteListener((track) => {
            this.node_logo.paused = true;
            this.node_logo.setCompleteListener(null);
            this.node_logo.clearTrack(0);
            this.node_logo.skeletonData = null;
            this.playEnd();
        });

        resources.load('animation/logo/LOGO', sp.SkeletonData, (error, json) => {
            let data = json;
            this.node_logo.skeletonData = data;
            this.node_logo.node.active = true;
            let trackEntry = this.node_logo.setAnimation(0, "animation1", false);
            if (!trackEntry) {
                this.playEnd();
            }
            this.changeScreen();
        })

    }


    /**
     * 加载自定义logo
     */
    private loadCustom() {
        this.loadJson(this._logoSkeUrl)
            .then((skeData: any) => {
                this._logoAssetsList.push(skeData);
                this.loadJson(this._logoAtlasUrl)
                    .then((atlasData: any) => {
                        this._logoAssetsList.push(atlasData);
                    })
                    .then(() => {
                        console.log('JSON loaded:');
                        return Promise.all(this._logoResUrl.map(url => this.loadTexture(url)))
                            .then(() => {
                                Log.d('LOGO spine ani is loaded');
                                this.playCustom();
                                this.changeScreen();
                            })
                            .catch(() => {
                                this.showWarn();
                            })
                    })
                    .catch(() => {
                        this.showWarn();
                    })
            })
            .catch(() => {
                this.showWarn();
            })
    }

    private showWarn() {
        console.warn('There is a problem with the backend configuration of the logo!!!')
        this.playEnd();
    }

    private playCustom() {
        let asset = new sp.SkeletonData();
        asset.skeletonJson = this._logoAssetsList[0];
        asset.atlasText = this._logoAssetsList[1];
        asset.textures = this._logoTexList;
        asset.textureNames = this._logoTexNameList;

        this.node_logo.node.active = true;
        this.node_logo.clearTrack(0);
        this.node_logo.skeletonData = asset;
        this.node_logo.setToSetupPose();
        let boxAni = "animation1";
        this.node_logo.timeScale = 1;
        this.node_logo.setCompleteListener((track) => {
            this.node_logo.paused = true;
            this.node_logo.setCompleteListener(null);
            this.node_logo.clearTrack(0);
            this.node_logo.skeletonData = null;
            this.playEnd();
        });
        let trackEntry = this.node_logo.setAnimation(0, boxAni, false);
        if (!trackEntry) {
            this.playEnd();
        }
    }

    async loadJson(url) {
        return fetch(url)
            .then(response => {
                if (!response.ok) {
                    throw new Error('Network response was not ok');
                }
                return response.text();
            });
    }

    async loadTexture(url: string) {
        return new Promise(async (resolve, reject) => {
            await assetManager.loadRemote(url, (error, img: ImageAsset) => {
                let texture2d = new Texture2D();
                texture2d.image = img;
                let textureName = url.substring(url.lastIndexOf("/") + 1);
                this._logoTexList.push(texture2d);
                this._logoTexNameList.push(textureName);
                resolve(null);
            });
        });
    }

    /** 文件类型 */
    private getFileType(filePath: string): string | undefined {
        const fileExtension = filePath.split('.').pop(); // 获取文件的扩展名
        return fileExtension?.toLowerCase(); // 返回小写的扩展名（如果存在）
    }

    /** 文件名 */
    private getFileName(filePath: string): string | undefined {
        const name = filePath.split('/').pop(); // 获取文件的扩展名
        const extension = name.split('.')[0];
        return extension;
    }

    update(deltaTime: number) {

    }

    /** 
     * 播放结束
     * 无需播放logo，也会调用此方法
     */
    private playEnd() {
        let obj = {
            gameid: Global.gameId,
            skip: Global.logoType == LOGO_PLAY_TYPE.NONE ? 0 : 1 //是否已跳过
        }
        GameUtils.c2javaMarkByShort('logo_played', obj);

        if (this._callback)
            this._callback();
    }

    /**
     * 横竖屏切换
     */
    private changeScreen() {
        let state = this.node_logo.getState();
        if (!state)
            return;
        let track = state.tracks[0];
        if (!track)
            return;
        let trackTime = track.trackTime;
        let boxAni = "";

        if (Global.gameScreenType == ScreenType.Portrait) {
            boxAni = "animation2";
            this.node_logo.node.angle = 90;
        } else {
            boxAni = "animation1";
            this.node_logo.node.angle = 0;
        }
        this.node_logo.setAnimation(0, boxAni, false);
        let track2 = this.node_logo.getState().tracks[0];
        track2.trackTime = trackTime;
    }

    protected onDestroy(): void {
        Eventer.getInstance().offName(Events.ScreenSwitchEvent, this);
    }

}