export type AccountInfo = {
    account: string;
    password: string;
    guester: string | undefined;
}
/**
 * 游戏服务端信息
 */
export interface ISvrGameInfo {
    /**游戏id*/
    gameid: number;
    /**游戏名称*/
    gamename: string;
    /**游戏文件大小，兼容未开发完的游戏入口的容错处理*/
    filesize: number;
    /**游戏的版本，兼容未开发完的游戏入口的容错处理*/
    version: string;
    /**游戏类型*/
    gametype: EGAME_TYPE;
    /**收藏 1： 是， 0： 否*/
    collect: number;
    /**热门 1： 是， 0： 否*/
    hot: number;
    /**最新 1： 是， 0： 否*/
    new: number;
    /**加载不同游戏的标签*/
    req: string;
    /**彩金*/
    bonus: number;
    /**游戏图标url */
    imageurl: string;
    /**是否长图 */
    is_length: number;
    /**游戏显示标签分类*/
    tags: Array<string>;
    /**游戏启动图*/
    bg_image: string;
    /**供应商 */
    vendor?: string; 
}
/**游戏客户端资源配置*/
export interface IClientGameConfig {
    /**是否区分资源 0:不区分，1:区分pvrt，etc1*/
    os: ECLIENT_GAME_RES_DIFF;
    normal?: IClientGameVersion;
    etc1?: IClientGameVersion;
    pvrtc?: IClientGameVersion;
    appType?: APP_TYPE
}

export interface IClientGameVersion {
    /**eg: 0.1.2 as 0 留空位，1表示大版本，2表示小版本，更新完大版本后须再更新小版本*/
    /**小版本是0的时候不用更新小版本，不是0就要更*/
    version: string;
    bigsize: number;
    subsize?: number;
}

/**
 * 游戏版本结构体
 **/
export type VerInfo = {
    /**游戏id*/
    id: number;
    /**版本*/
    version: string;
}

export class HttpResponseType {
    /**
     * Specifies that downloaded data is received as text. This is the default value of HttpRequest.responseType
     * @version Egret 2.4
     * @platform Web,Native
     * @language en_US
     */
    /**
     * 返回字符串。HttpRequest.responseType属性的默认值。
     * @version Egret 2.4
     * @platform Web,Native
     * @language zh_CN
     */
    static TEXT: string;
    /**
     * Specifies that downloaded data is received as raw binary data.
     * @version Egret 2.4
     * @platform Web,Native
     * @language en_US
     */
    /**
     * 返回二进制的ArrayBuffer对象。
     * @version Egret 2.4
     * @platform Web,Native
     * @language zh_CN
     */
    static ARRAY_BUFFER: string;
}
export class URLLoaderDataFormat {
    /**
     * Specify that downloaded data is received as raw binary data.
     * @version Egret 2.4
     * @platform Web
     * @language en_US
     */
    /**
     * 指定以原始二进制数据形式接收下载的数据。
     * @version Egret 2.4
     * @platform Web
     * @language zh_CN
     */
    static BINARY: string;
    /**
     * Specify that downloaded data is received as text.
     * @version Egret 2.4
     * @platform Web,Native
     * @language en_US
     */
    /**
     * 指定以文本形式接收已下载的数据。
     * @version Egret 2.4
     * @platform Web,Native
     * @language zh_CN
     */
    static TEXT: string;
    /**
     * Specify that downloaded data is received as URL-encoded variables.
     * @version Egret 2.4
     * @platform Web,Native
     * @language en_US
     */
    /**
     * 指定以 URL 编码变量形式接收下载的数据。
     * @version Egret 2.4
     * @platform Web,Native
     * @language zh_CN
     */
    static VARIABLES: string;
    /**
     * Specify that downloaded data is received as bitmap texture.
     * @version Egret 2.4
     * @platform Web,Native
     * @language en_US
     */
    /**
     * 指定以位图纹理形式接收已下载的数据。
     * @version Egret 2.4
     * @platform Web,Native
     * @language zh_CN
     */
    static TEXTURE: string;
    /**
     * Specify that downloaded data is received as sound.
     * @version Egret 2.4
     * @platform Web,Native
     * @language en_US
     */
    /**
     * 指定以声音形式接收已下载的数据。
     * @version Egret 2.4
     * @platform Web,Native
     * @language zh_CN
     */
    static SOUND: string;
}
