import { Component, Label, _decorator } from 'cc';
import DateUtil from './DateUtil';


const { ccclass, executeInEditMode, requireComponent, menu } = _decorator;

/**
 * 倒计时组件
 */
@ccclass
@executeInEditMode
@requireComponent(Label)
@menu('ui/common/Countdown')
export default class Countdown extends Component {
    /**回调函数 */
    private callback: Function;
    /**回调函数对象*/
    private thisArg: any;
    /**总共的时间戳 */
    private totalTime: number = -1;
    /**是否停止倒计时 */
    private bStop: boolean = true;
    /**格式化方式，如（'hh:mm:ss'）
     * ss:显示为10s
     * */
    private format: string;

    start() {
        this.format = this.format ?? 'hh:mm:ss';
        this.string = 0;
    }

    /**
     * 启动倒计时
     * @param residueTime 剩余的时间戳（精确到秒）
     * @param callback 回调
     */
    run(residueTime: number, callback?: Function, format?: string, thisArg?: any) {
        if (residueTime == null || residueTime < 0) return;
        this.bStop = false;
        if (format && format != '') this.format = format;
        this.callback = callback;
        this.thisArg = thisArg;
        this.totalTime = residueTime + this.getSysTimes();
    }

    /**
     * 显示倒计时
     */
    set string(time: number) {
        let label = this.getComponent(Label);
        if (label && this.totalTime >= 0) {
            label.string = DateUtil.formatCountDwon(time, this.format);
        }
    }

    update(dt: any) {
        if(this.bStop) {
            return;
        }
        var sysTimes = this.getSysTimes();
        let time = Math.floor(this.totalTime - sysTimes);
        if (time >= 0) {
            this.string = this.totalTime - sysTimes;
        } else {
            this.stop();
        }
    }

    /**
     * 倒计时结束
     */
    stop() {
        if (!this.bStop) {
            this.bStop = true;
            this.string = 0;
            if(this.thisArg && this.callback) {
                this.callback.apply(this.thisArg);
            } else if (this.callback) {
                this.callback();
            }
        }
    }

    /**
     * 获取系统时间（精确到秒）
     * @returns
     */
    getSysTimes() {
        return new Date().getTime() / 1000;
    }
}
