import { Asset, assetManager, game, JsonAsset, native, sys } from "cc";
import { NetErrCode } from "../../common/define/StatisticsDefine";
import LogUtil from "../../common/utils/LogUtil";
import { Singleton } from "../Singleton";
import UIUtils from "../ui/UIUtils";
import i18n from "../language/i18n";

let hotUpdatePath = 'remotePath';
let hotUpdateSearchPaths = 'HotUpdateSearchPaths';

export interface UpdateParams {
    /**必须传project.manifest，不能传version.manifest，否则第一次更新会更新所有资源， */
    asset: Asset;
    /**是否可以更新回调 */
    onUpdate: Function;
    /**更新进度回调 */
    onProgress: Function;
    /**更新失败回调 */
    onFail: Function;
    /**白名单参数 */
    whiteParams?: WhiteListParams;
}

export interface WhiteListParams {
    whitelistUrl?: string;
    spaceId?: string;
    deviceid?: string;
    uid?: string;
}

const MANIFEST_NAME = "project.manifest";
const MANIFEST_PATHS = {
    packageUrl: "packageUrl",
    remoteManifestUrl: "remoteManifestUrl",
    remoteVersionUrl: "remoteVersionUrl",
    whiteListConfigUrl: "whiteListConfigUrl",
};

/**
 * 热更新
 */
export default class HotUpdate extends Singleton<HotUpdate>() {
    am: native.AssetsManager = null;
    private _updating: boolean = false;
    private _canRetry: boolean = false;
    private params: UpdateParams = null;
    private _localVersion: string = '1.0.0';
    storagePath: string = '';
    private timeout: any = null;
    private platformId = 0;
    private cdnUrl = '';
    private manifestJsonData = null;

    /**白名单匹配规则 */
    private whitelistMatchRule = {
        whiteList: 'deviceid',
        uidList: 'uid',
        uidRegular: 'uid',
        deviceidList: 'deviceid',
        deviceidRegular: 'deviceid',
        uninionidList: 'unionid',
        unionidRegular: 'unionid',
    };

    /**
     * 获得本地版本
     * @returns
     */
    public getLocalVersion() {
        return this._localVersion;
    }

    /**
     * 获取是否正在更新
     */
    get updating() {
        return this._updating;
    }

    /**
     * 初始化
     */
    init(platformId: number, cdnUrl: string) {
        if (!sys.isNative) {
            return;
        }
        this.manifestJsonData = null;
        this.platformId = platformId;
        this.cdnUrl = cdnUrl;
        let dir = platformId ? (platformId + "/") : "";
        this.storagePath =
            (native.fileUtils ? native.fileUtils.getWritablePath() : '/') + dir + hotUpdatePath;
        this.am = new native.AssetsManager('', this.storagePath, this.versionCompareHanle);
        let assetsVerifyCallback = (path: string, asset: any) => {
            let compressed = asset.compressed;
            let expectedMD5 = asset.md5;
            let relativePath = asset.path;
            let size = asset.size;
            if (compressed) {
                Log.d('检查压缩 : ' + relativePath);
                return true;
            } else {
                Log.d('检查压缩 : ' + relativePath + ' (' + expectedMD5 + ')');
                return true;
            }
        };
        this.am.setVerifyCallback(assetsVerifyCallback);
    }

    /**
     * 检测更新
     * @param res 必须传project.manifest，不能传version.manifest，否则第一次更新会更新所有资源，
     * @param onLoad 是否可以更新回调
     * @param onProgress 更新进度回调
     * @param whiteListId 白名单id
     * @returns
     */
    checkUpdate(params: UpdateParams) {
        this.params = params;
        if (!sys.isNative || !this.params || !this.params.asset || this._updating || !this.am) {
            this.params.onUpdate(false);
            return;
        }
        if (this.am.getState() === native.AssetsManager.State.UNINITED) {
            this.loadManifest();
            let localMani = this.am.getLocalManifest();
            if (localMani && localMani.getVersion) {
                this._localVersion = localMani.getVersion();
            }
        }
        if (!this.am.getLocalManifest() || !this.am.getLocalManifest().isLoaded()) {
            this.params.onUpdate(false);
            return;
        }
        let _this = this;
        //检查manifest
        this.checkManifest(String(this.platformId), this.cdnUrl);
        let checkUpdateCallback = function (event: any) {
            if (_this.timeout) {
                clearTimeout(_this.timeout);
                _this.timeout = null;
                UIUtils.closeTips();
            }
            Log.d('checkUpdate Code: ' + event.getEventCode());
            let code = event.getEventCode();
            if (code == native.EventAssetsManager.NEW_VERSION_FOUND) {
                _this.params.onUpdate(true);
                _this.am.setEventCallback(null);
                _this._updating = false;
                _this.hotUpdateStart();
            } else if (code == native.EventAssetsManager.ERROR_DOWNLOAD_MANIFEST) {
                _this.onFail(NetErrCode.manifest);
            } else if (
                code == native.EventAssetsManager.ERROR_NO_LOCAL_MANIFEST ||
                code == native.EventAssetsManager.ERROR_PARSE_MANIFEST ||
                code == native.EventAssetsManager.ALREADY_UP_TO_DATE ||
                code == native.EventAssetsManager.UPDATE_FINISHED
            ) {
                _this.params.onUpdate(false);
                _this.am.setEventCallback(null);
                _this._updating = false;
            }
        };

        this.am.setEventCallback(checkUpdateCallback);
        this.am.checkUpdate();
        this._updating = true;

        /**
         * 白名单检测，(暂不需要白名单功能)
         *  无白名单走正常更新
         *  有白名单更新白名单版本
         */
        // this.checkWhite(this.params.whiteParams, (pass: boolean, whiteList?) => {
        //     let check = () => {
        //         if(this.timeout)clearTimeout(this.timeout);
        //         this.timeout = setTimeout(() => {
        //             this.onFail(NetErrCode.hotTimeOut);
        //         }, 8000);
        //         this.am.setEventCallback(checkUpdateCallback);
        //         this.am.checkUpdate();
        //         this._updating = true;
        //     };
        //     Log.d(`===checkWhite===${pass}==${whiteList}==`);
        //     if (pass && whiteList) {
        //         this.editWhiteManifest(whiteList, () => {
        //             check();
        //         });
        //     } else {
        //         if (!whiteList) {
        //             this.onFail(NetErrCode.whiteList);
        //         } else {
        //             check();
        //         }
        //     }
        // });
    }

    /**
     * 开始更新
     * @returns
     */
    hotUpdateStart() {
        if (this.am && !this._updating) {
            this.am.setEventCallback(this.updateCallback.bind(this));
            if (this.am.getState() === native.AssetsManager.State.UNINITED) {
                this.loadManifest();
                let localMani = this.am.getLocalManifest();
                if (localMani && localMani.getVersion) {
                    this._localVersion = localMani.getVersion();
                }
            }
            this.am.update();
            this._updating = true;
        }
    }

    /**比较版本 版本不同则更新*/
    versionCompareHanle(versionA: string, versionB: string) {
        Log.d(`当前版本 :  ${versionA} , 远程版本 : ${versionB}`);
        let vA = versionA.split('.');
        let vB = versionB.split('.');
        for (let i = 0; i < vA.length && i < vB.length; ++i) {
            let a = parseInt(vA[i]);
            let b = parseInt(vB[i]);
            if (a === b) {
                continue;
            } else {
                //版本不同就更新
                return -1;
                //大于当前版本才更新
                // return a - b;
            }
        }
        if (vB.length > vA.length) {
            return -1;
        }
        return 0;
    }

    /**
     * 热更新回调
     * @param event
     * @returns
     */
    updateCallback(event: any) {
        let needRestart: boolean = false;
        let failed: boolean = false;
        let panel_info_string: string = null;
        let update_percent = null;
        Log.d('2Code: ' + event.getEventCode());
        switch (event.getEventCode()) {
            case native.EventAssetsManager.ERROR_NO_LOCAL_MANIFEST:
                // panel_info_string = i18n.t('LabelHotUpdate10');
                Log.d('本地没有manifest文件，更新失败');
                failed = true;
                break;
            case native.EventAssetsManager.UPDATE_PROGRESSION:
                update_percent = Math.floor(event.getPercentByFile() * 100) / 100;
                let down_byte = Math.ceil(event.getDownloadedBytes() / 1024);
                let total_byte = Math.ceil(event.getTotalBytes() / 1024);
                if (total_byte > 0) panel_info_string = down_byte + ' / ' + total_byte + 'kb';
                break;
            case native.EventAssetsManager.ERROR_DOWNLOAD_MANIFEST:
            case native.EventAssetsManager.ERROR_PARSE_MANIFEST:
                Log.d('下载manifest文件失败!');
                failed = true;
                break;
            case native.EventAssetsManager.ALREADY_UP_TO_DATE:
                Log.d('已经更新到最新版本!');
                if (this.params.onProgress) {
                    this.params.onProgress.call(this, true, 1, panel_info_string);
                }
                this._updating = false;
                return;
            case native.EventAssetsManager.UPDATE_FINISHED:
                panel_info_string = 'update success!'//i18n.tr(310042);
                Log.d('更新成功!');
                needRestart = true;
                break;
            case native.EventAssetsManager.UPDATE_FAILED:
                Log.d(`更新失败!${event.getMessage()}`);
                this.onFail(NetErrCode.hotFiles);
                break;
            case native.EventAssetsManager.ERROR_UPDATING:
                Log.d(`资源更新失败!${event.getAssetId()},${event.getMessage()}`);
                break;
            case native.EventAssetsManager.ERROR_DECOMPRESS:
                Log.d(`资源解压失败!${event.getMessage()}`);
                break;
            default:
                break;
        }

        if (this.params.onProgress) {
            this.params.onProgress.call(this, false, update_percent, panel_info_string);
        }

        if (failed) {
            this.am.setEventCallback(null);
            this._updating = false;
        }

        if (needRestart) {
            if (this.params.onProgress) {
                this.params.onProgress.call(this, true, update_percent, panel_info_string);
            }
            this.am.setEventCallback(null);
            let searchPaths = native.fileUtils.getSearchPaths();
            let localManifest = this.am.getLocalManifest();
            if (localManifest) {
                Array.prototype.unshift.apply(searchPaths, localManifest.getSearchPaths());
            }
            sys.localStorage.setItem(hotUpdateSearchPaths, JSON.stringify(searchPaths));
            native.fileUtils.setSearchPaths(searchPaths);
            // audioEngine.stopAll();
            if (sys.isNative) {
                game.restart();
            }
        }
    }

    /**
     * 下载失败时候，重新下载
     */
    retry() {
        if (!this._updating && this._canRetry && this.am) {
            this._canRetry = false;
            this.am.downloadFailedAssets();
        }
    }

    onFail(errCode: number) {
        this._updating = false;
        if (this.params && this.params.onFail) {
            this.params.onFail.call(this, errCode);
        }
    }

    private loadManifest() {
        if (!this.params.asset) return;
        let url = this.params.asset.nativeUrl;
        this.am.loadLocalManifest(url);
    }

    /**
     * 匹配判断
     * @param checkId
     * @param matchList
     * @param useRegular
     * @returns
     */
    private matchIdByList(checkId, matchList, useRegular) {
        checkId = checkId.toString();
        for (let matchId of matchList) {
            if (useRegular) {
                if (checkId.match(matchId.toString())) {
                    return true;
                }
            } else if (checkId == matchId.toString()) {
                return true;
            }
        }
    }

    /**
     * 白名单灰度匹配
     * @param params 匹配参数
     * @param whitelist 白名单列表
     * @param force_rule 匹配规则
     * @returns
     */
    isWhitelistGrayMatch(params: WhiteListParams, whitelist, force_rule?) {
        let pass = false;
        let ruleConfig = force_rule ?? whitelist.rule ?? ['uidList'];
        if (ruleConfig.length == 0) {
            ruleConfig = ['uidList'];
        }
        for (let anyPassList of ruleConfig) {
            let allPassed = true;
            for (let rule of anyPassList.split(',')) {
                let paramName = this.whitelistMatchRule[rule] ?? '';
                let useRegular = rule.match('(.*)Regular');
                let check_id = params[paramName];
                let ruleMatchList = whitelist[rule] ?? {};
                if (!check_id || !this.matchIdByList(check_id, ruleMatchList, useRegular)) {
                    allPassed = false;
                }
            }
            if (allPassed) {
                pass = true;
                break;
            }
        }
        return pass;
    }

    /**
     * 白名单检测
     * @param params 匹配参数
     * @returns
     */
    checkWhite(params: WhiteListParams, callback: Function) {
        let pass = false;
        if (!params) {
            callback(pass);
            return pass;
        }
        let whiteUrl = null;
        let jsonData = this.getStorageManifestData();
        if (jsonData) whiteUrl = jsonData.whiteListConfigUrl;
        if (!whiteUrl) {
            callback(pass);
            return pass;
        }
        Log.d(`====checkWhite url===${whiteUrl}=====`);
        let timeout = setTimeout(() => {
            callback(pass);
            return pass;
        }, 3000);
        assetManager.loadRemote(whiteUrl, (err, jsonAsset: JsonAsset) => {
            if (timeout) clearTimeout(timeout);
            if (err || !jsonAsset || !jsonAsset.json) {
                LogUtil.warn('load whiteList fail!' + err);
                callback(pass);
                return pass;
            }
            let whitelist = jsonAsset.json;
            if (whitelist['openWhitelist'] == true || whitelist['openWhitelist'] == 'true') {
                if (this.isWhitelistGrayMatch(params, whitelist, ['whiteList'])) {
                    pass = true;
                }
            } else if (whitelist['openGray'] == true || whitelist['openGray'] == 'true') {
                if (this.isWhitelistGrayMatch(params, whitelist)) {
                    pass = true;
                }
            }
            assetManager.releaseAsset(jsonAsset);
            callback(pass, whitelist);
        });
    }

    /**
     * 修改白名单manifest
     * @param remoteUrl
     * @param callback
     */
    editWhiteManifest(whiteList, callback) {
        let jsonData = this.getStorageManifestData();
        jsonData.remoteManifestUrl = whiteList.remoteManifestUrl;
        jsonData.remoteVersionUrl = whiteList.remoteVersionUrl;
        let afterString = JSON.stringify(jsonData);
        // native.fileUtils.writeStringToFile(afterString, fileName);
        // let flag = this.am.loadLocalManifest(storagePath);
        let manifest = this.am.getLocalManifest();
        manifest.parseJSONString(afterString, manifest.getManifestRoot());
        Log.d(
            `===editWhiteManifest2===${whiteList.remoteManifestUrl
            }==${manifest.getManifestFileUrl()}==`
        );
        if (callback) callback();
    }

    /**
     * 获取缓冲区manifest
     * @returns 
     */
    getStorageManifestData() {
        if (!this.params) return;
        if (this.manifestJsonData) return this.manifestJsonData;
        let fileName = this.storagePath + MANIFEST_NAME;
        let url = '';
        if (native.fileUtils.isFileExist(fileName)) {
            url = fileName;
        } else {
            url = this.params.asset.nativeUrl;
        }
        let loadManifest = native.fileUtils.getStringFromFile(url);
        let jsonData = JSON.parse(loadManifest);
        this.manifestJsonData = jsonData;
        return jsonData;
    }

    /**
     * 检查project.manifest
     * 如果cdn地址不一样，重定向cdn地址
     * @param platformId
     * @param cdnUrl
     */
    checkManifest(platformId: string, cdnUrl: string) {
        if (!sys.isNative || platformId == null || Number(platformId) <= 0)
            return;
        if (!cdnUrl || cdnUrl === "") return;
        let hotUpdate = HotUpdate.getInstance();
        let jsonData = hotUpdate.getStorageManifestData();
        if (!jsonData) return;
        let packageUrl = jsonData[MANIFEST_PATHS.packageUrl];
        if (!packageUrl) return;
        if (String(packageUrl).indexOf(cdnUrl) == -1) {
            for (let i in MANIFEST_PATHS) {
                let path = jsonData[i] as string;
                if (!path) {
                    Log.w(`No manifest path=${path} found! `);
                    return;
                } else {
                    let pos1 = this.findPos(path, "/", 2);
                    path = path.replace(path.substring(0, pos1), cdnUrl);
                    let pos2 = this.findPos(path, "/", 3);
                    let pos3 = this.findPos(path, "/", 4);
                    if (pos3 > pos2) {
                        path = path.replace(
                            path.substring(pos2 + 1, pos3),
                            platformId
                        );
                        jsonData[i] = path;
                    } else {
                        Log.w(`manifest replace url error=${i}! `);
                        return;
                    }
                    Log.d(`=manifest replace success!=${i}=${path}==`);
                }
            }
            jsonData['version'] = '1.0.0';
            let afterString = JSON.stringify(jsonData);
            let manifest = hotUpdate.am.getLocalManifest();
            manifest.parseJSONString(afterString, manifest.getManifestRoot());
        }
    }

    /**
     * 查找子串出现第N次的位置
     * @param str
     * @param reg
     * @param n
     * @returns
     */
    findPos(str: string, reg: string, n: number) {
        var x = str.indexOf(reg);
        for (var i = 0; i < n; i++) {
            x = str.indexOf(reg, x + 1);
        }
        return x;
    }
}
