import { Label, Node, _decorator } from "cc";
import { ScreenType, UIView, UIZIndex } from "./UIView";
import { UIButton } from "./basic_ui/UIButton";
import { Global } from "../../main/Global";
import { GameModel } from "../../main/GameModel";
import { GameUtils } from "../../common/utils/GameUtil";
import { Eventer } from "../Eventer";
import { Events } from "../Events";
import UIUtils from "./UIUtils";
import i18n from "../language/i18n";
const { ccclass, property } = _decorator;

@ccclass("PopupView")
export class UIPopupView extends UIView {

    @property({ displayName: "btn_0", type: UIButton })
    private btn_0: UIButton;
    @property({ displayName: "node_0", type: Node })
    private node_0: Node;
    @property({ displayName: "btn_1", type: UIButton })
    private btn_1: UIButton;
    @property({ displayName: "node_1", type: Node })
    private node_1: Node;
    @property({ displayName: "lab_txt", type: Label })
    private lab_txt: Label;

    private _code: number;
    private _popupConfig: any;
    /**倒计时 */
    private _time: number = 0;
    private _onTimeFun: Function;

    init(...args): void {

        this.node.zIndex = UIZIndex.popup;

        let mData = args[0];
        this._code = mData.code;
        if (!this._code) {
            return;
        }
        this._popupConfig = GameUtils.copyTab(GameModel.getInstance().getPopupDataById(mData.code));
        if (!this._popupConfig) {
            return;
        }

        this._onTimeFun = this.onTime.bind(this);
        this._showView(mData.args);
        this.addToStage();
    }
    protected onDestroy(): void {
        Eventer.getInstance().offName(Events.ScreenSwitchEvent, this);
        // this._code=null;
        // this._popupConfig=null;
        // this._time=null;
        // this._onTimeFun=null;
        // this.removeFromStage();
    }

    public onOpen(...args): void {
        super.onOpen(...args);
        this.changeScreen();
    }

    /**
     * 设置信息 显示内容
     * @returns 
     */
    private _showView(args: any) {
        let txt = GameModel.getInstance().getPopupStrById(this._code);
        let time = this._popupConfig.time;
        if (this._popupConfig.type == 1) { //客户端
            if (time > 0) {
                this._time = time;
                txt = GameUtils.replaceString(txt, [this._time]);
                this._timeDown();
            }
        }
        else {  //服务端
            txt = GameUtils.replaceString(txt, args);
        }
        this._setLabel(txt);

        //隐藏按钮
        let hideBtn = (operate): boolean => {
            if (operate === 11 || operate === 12 || operate === 13)
                if (Global.closeBack || Global.homeUrl == '')
                    return true;
            return false;
        }

        let count = 0;
        let buttons = this._popupConfig.button;
        if (buttons[0]) {
            let hide = hideBtn(this._popupConfig.button[0].operate);
            if (buttons[0].state <= 0)
                this.node_0.active = false;
            else {
                this.node_0.active = true;
                this._setBtnSprite(this.btn_0, buttons[0].state);
                count++;
            }
        }
        if (buttons[1]) {
            let hide = hideBtn(this._popupConfig.button[1].operate);
            if (hide || buttons[1].state <= 0)
                this.node_1.active = false;
            else {
                this.node_1.active = true;
                this._setBtnSprite(this.btn_1, buttons[1].state);
                count++;
            }
        }
    }

    public setPopupData(key: number, serverArgs: string[] = null): void {
        let newConfig: any = GameModel.getInstance().getPopupDataById(key);
        if (!newConfig) {
            return;
        }
        let oldPower: number = this._popupConfig.power;
        let newPower: number = newConfig.power;
        if (newPower > oldPower) {
            this._popupConfig = GameUtils.copyTab(newConfig);
            this._code = key;
            this._showView(serverArgs);
        }
    }

    /**
     * 设置提示内容
     * @param txt 文本提示
     */
    private _setLabel(txt: string) {
        this.lab_txt.getComponent(Label).string = txt;
    }

    /**
     * 设置按钮状态
     * @param btn 按钮
     * @param state 状态
     */
    private _setBtnSprite(btn: UIButton, state: number) {
        let lableId: number = 0;
        //重连
        if (state == 1) {
            lableId = 1003017;
        }
        //返回
        else if (state == 2) {
            lableId = 1003016;
        }
        //继续
        else if (state == 3) {
            lableId = 1003018;
        }
        //确定
        else if (state == 4) {
            lableId = 1003015;
        }
        btn.btnLable.string = i18n.tr(lableId);
    }

    /**按钮0 点击事件 */
    private _btn0Call(target: UIButton): void {
        let operate: number = this._popupConfig.button[0].operate;
        if (operate > -1) {
            Eventer.getInstance().emit(Events.UIPopupBtn, operate);
        }
        this.close();
    }

    /**按钮1 点击事件 */
    private _btn1Call(target: UIButton): void {
        let operate: number = this._popupConfig.button[1].operate;
        if (operate > -1) {
            Eventer.getInstance().emit(Events.UIPopupBtn, operate);
        }
        this.close();
    }

    /**
     * 倒计时
     */
    private _timeDown() {
        this.unschedule(this._onTimeFun);
        this.schedule(this._onTimeFun, 1);
    }

    private onTime(evt): void {
        this._time--;
        if (this._time <= 0) {
            this._time = 0;
        }
        let txt = GameModel.getInstance().getPopupStrById(this._code);
        txt = GameUtils.replaceString(txt, [this._time]);
        this._setLabel(txt);
        if (this._time == 0) {
            if (this._code == 11001) {
                UIUtils.showPopupView(40003);
                Eventer.getInstance().emit(Events.StatMarkEvent, 'NO_OPERATION');
                Eventer.getInstance().emit(Events.CloseGameSocketEvent);
            }
            this.unschedule(this._onTimeFun);
            if (this._popupConfig["timeout"] == 0) {
                this._btn0Call(null);
            }
            else if (this._popupConfig["timeout"] == 1) {
                this._btn1Call(null);
            }
        }
    }

    protected addToStage() {
        this.btn_0.touchEndedFun = this._btn0Call.bind(this);
        this.btn_1.touchEndedFun = this._btn1Call.bind(this);
        Eventer.getInstance().on(Events.ScreenSwitchEvent, this.changeScreen, this);
    }

    protected removeFromStage() {
        this.btn_0.touchEndedFun = null;
        this.btn_0 = null;
        this.btn_1.touchEndedFun = null;
        this.btn_1 = null;
        this.lab_txt = null;

        this.unschedule(this._onTimeFun);
    }

    // private readonly _L_SCALE: math.Vec3 = new math.Vec3(1, 1, 1);
    // private readonly _P_SCALE: math.Vec3 = new math.Vec3(0.56, 0.56, 0.56);
    // 横竖屏切换显示
    private changeScreen(): void {
        let contentNode: Node = this.node.getChildByName("content");
        if (Global.gameScreenType == ScreenType.Portrait) {
            contentNode.angle = 90;
        } else {
            contentNode.angle = 0;
        }
    }

}