import {
    assetManager,
    ImageAsset,
    Node,
    Sprite,
    SpriteFrame,
    sys,
    Texture2D,
    v2,
    v3,
} from "cc";
export class CCUtils {
    // static asyncLoadRes(path: string) {
    //     let p = new Promise((resolve, reject) => {
    //         setTimeout(() => {
    //             resolve(true);

    //         }, 2000);

    //     });
    //     return p;
    // }
    static changeNodePosY(node: Node, posY: number) {
        node.setPosition(v3(node.position.x, posY, node.position.z));
    }
    static splitStr(string: string, str: string) {
        //根据指定字符分割字符串，获取指定字符前后的字符串
        let strObj = { str_before: "", str_after: "" };
        let str_before = string.split(str)[0];
        let str_after = string.split(str)[1];
        //@ts-ignore
        strObj.str_before = str_before;
        //@ts-ignore
        strObj.str_after = str_after;
        return strObj;
    }
    static parseURL(url: string) {
        //解析GET请求url上?后的请求参数，将请求参数从url上取下来，放到{}中
        let result: any = {},
            seg = url.split("&"),
            len = seg.length,
            i = 0,
            s;
        for (; i < len; i++) {
            if (!seg[i]) {
                continue;
            }
            s = seg[i].split("==");
            s[1] = s[1].replace(/%/g, "%25");
            result[s[0]] = decodeURIComponent(s[1]);
        }
        return result;
    }
    static setSpriteFrame(
        sprite: Sprite,
        url: string,
        callback?: (error: any, spriteFrame: SpriteFrame) => void
    ) {
        assetManager.loadRemote<ImageAsset>(
            url,
            function (err: Error, imageAsset: ImageAsset) {
                const spriteFrame = new SpriteFrame();
                const texture = new Texture2D();
                texture.image = imageAsset;
                spriteFrame.texture = texture;
                if (!err) {
                    sprite.spriteFrame = spriteFrame;
                } else {
                    sprite.spriteFrame = null;
                }
                callback && callback(err, sprite.spriteFrame!);
            }
        );
    }
    /**递归遍历所有子节点 */
    static getAllChildrenRecursion = (node: Node): Array<Node> => {
        let allNodeArr: Array<Node> = [];
        allNodeArr.push(node);
        let func = (_node: Node) => {
            if (_node.children.length > 0) {
                for (let i = 0; i < _node.children.length; i++) {
                    allNodeArr.push(_node.children[i]);
                    if (_node.children[i].children) {
                        if (_node.children[i].children.length > 0) {
                            func(_node.children[i]);
                        }
                    }
                }
            }
        };
        func(node);
        return allNodeArr;
    };

    /**递归遍历所有子节点 */
    static getAllComponentsRecursion = <T>(
        node: Node,
        type: T
    ): Array<Node> => {
        let allNodeArr: Array<Node> = [];
        if (node.getComponent(type as any)) {
            allNodeArr.push(node);
        }
        let func = (_node: Node) => {
            if (_node.children.length > 0) {
                for (let i = 0; i < _node.children.length; i++) {
                    if (node.getComponent(type as any)) {
                        allNodeArr.push(_node.children[i]);
                    }
                    if (_node.children[i].children) {
                        if (_node.children[i].children.length > 0) {
                            func(_node.children[i]);
                        }
                    }
                }
            }
        };
        func(node);
        return allNodeArr;
    };
}
